// Fraction template for CPP

class Fraction {
    private:
    ll GCD(ll a, ll b) {
        for(ll rem; b > 0; rem = a % b, a = b, b = rem);
        return a;
    }
    ll LCM(ll a, ll b) {
        return (a * b) / GCD(a, b);
    }
    public:
    ll num = 0, den = 1;
    Fraction() {
        num = 0;
        den = 1;
    };
    Fraction(ll n) {
        num = n;
        den = 1;
    };
    Fraction(ll n, ll d) {
        if(d == 0) {
            throw invalid_argument("Expected Non-Zero denominator");
        }
        num = n;
        den = d;
        ll g = GCD(num, den);
        num /= g;
        den /= g;
    };
    Fraction(Fraction& f) {
        num = f.num;
        den = f.den;
    };
    Fraction(string s) {
        int pos = s.find('/');
        if(pos != string::npos) {
            num = stoll(s.substr(0, pos));
            den = stoll(s.substr(pos + 1, s.size()));
            ll g = GCD(num, den);
            num /= g;
            den /= g;
        }
        else {
            num = stoll(s);
            den = 1;
        }
    };
    operator string() const {
        if(den == 1)
            return to_string(num);
        return to_string(num) + "/" + to_string(den);
    }
    Fraction operator + (const Fraction& frac) {
        ll l = LCM(den, frac.den);
        ll a = num * (l / den);
        ll b = frac.num * (l / frac.den);
        return Fraction(a + b, l);
    }
    void operator += (const Fraction& frac) {
        Fraction f = Fraction(num, den);
        f = (f + frac);
        num = f.num;
        den = f.den;
    }
    Fraction operator - (const Fraction& frac) {
        ll l = LCM(den, frac.den);
        ll a = num * (l / den);
        ll b = frac.num * (l / frac.den);
        return Fraction(a - b, l);
    }
    void operator -= (const Fraction& frac) {
        Fraction f = Fraction(num, den);
        f = (f - frac);
        num = f.num;
        den = f.den;
    }
    Fraction operator * (const Fraction& frac) {
        return Fraction(num * frac.num, den * frac.den);
    }
    void operator *= (const Fraction& frac) {
        Fraction f = Fraction(num, den);
        f = (f * frac);
        num = f.num;
        den = f.den;
    }
    Fraction operator / (const Fraction& frac) {
        return Fraction(num * frac.den, den * frac.num);
    }
    void operator /= (const Fraction& frac) {
        Fraction f = Fraction(num, den);
        f = (f / frac);
        num = f.num;
        den = f.den;
    }
    bool operator == (const Fraction& frac) {
        return (frac.num == num && frac.den == den);
    }
    bool operator != (const Fraction& frac) {
        return !(frac.num == num && frac.den == den);
    }
    bool operator < (const Fraction& frac) {
        ll base = LCM(den, frac.den);
        return (num * base/den) < (frac.num * base/frac.den);
    }
    bool operator <= (const Fraction& frac) {
        ll base = LCM(den, frac.den);
        return (num * base/den) <= (frac.num * base/frac.den);
    }
    bool operator > (const Fraction& frac) {
        ll base = LCM(den, frac.den);
        return (num * base/den) > (frac.num * base/frac.den);
    }
    bool operator >= (const Fraction& frac) {
        ll base = LCM(den, frac.den);
        return (num * base/den) >= (frac.num * base/frac.den);
    }
};
ostream& operator << (ostream& out, const Fraction& f) {
    if(f.den == 1)
        return out << to_string(f.num);
    return out << to_string(f.num) + "/" + to_string(f.den);
}

// End of Fraction template for CPP


class Graph {
    public:
    int V = 0;
    int E = 0;
    vector<vector<int>> graph;
    Graph(int v, int e) {
        V = v + 1;
        E = e;
        graph.resize(V, vector<int>());
    }

    void add_edge(int a, int b) {
        graph[a].push_back(b);
    }

    bool bfs(int start, int end) {
        vector<bool> visited(V, false);
        visited[start] = true;
        queue<int> q;
        q.push(start);
        while (!q.empty() && !visited[end]) {
            start = q.front();
            q.pop();
            for(int i: graph[start]) {
                if(!visited[i]) {
                    visited[i] = true;
                    q.push(i);
                }
            }
        }
        return visited[end];
    }

    void recurse(int start, vector<bool>& visited, int end) {
        if(start == end) {
            visited[start] = true;
            return;
        }
        visited[start] = true;
        for(int i: graph[start]) {
            if(!visited[i]) {
                recurse(i, visited, end);
            }
        }
    }

    bool dfs(int start, int end) {
        vector<bool> visited(V, false);
        recurse(start, visited, end);
        return visited[end];
    }
};

// NextGreater, NextSmaller at Right, Left

vector<int> next_greater_in_right(vector<int> a, int n) {
    vector<int> right_index(n, n);
    stack<int> st;
    for(int i = 0; i < n; i++) {
        while(!st.empty() && a[i] > a[st.top()]) {
            right_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return right_index;
}

vector<int> next_greater_in_left(vector<int>& a, int n) {
    vector<int> left_index(n, -1);
    stack<int> st;
    for(int i = n - 1; i >= 0; i--) {
        while(!st.empty() && a[i] > a[st.top()]) {
            left_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return left_index;
}

vector<int> next_smaller_in_right(vector<int>& a, int n) {
    vector<int> right_index(n, n);
    stack<int> st;
    for(int i = 0; i < n; i++) {
        while(!st.empty() && a[i] < a[st.top()]) {
            right_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return right_index;
}

vector<int> next_smaller_in_left(vector<int>& a, int n) {
    vector<int> left_index(n, -1);
    stack<int> st;
    for(int i = n - 1; i >= 0; i--) {
        while (!st.empty() && a[i] < a[st.top()]) {
            left_index[st.top()] = i;
            st.pop();
        }
        st.push(i);
    }
    return left_index;
}

