// ***************************************************************************************
// Polynomial Hash Functions

class Hash {
private:
    int length;
    const int mod1 = 1e9 + 7, mod2 = 1e9 + 9;
    const int p1 = 31, p2 = 37;
    vector<int> hash1, hash2;
    pair<int, int> hash_pair;
    const char seed = 'a';

public:
    inline static vector<int> inv_pow1, inv_pow2;
    inline static int inv_size = 1;

    Hash(const string& s) {
        length = s.size();
        hash1.resize(length);
        hash2.resize(length);

        int h1 = 0, h2 = 0;
        long long p_pow1 = 1, p_pow2 = 1;
        for(int i = 0; i < length; i++) {
            h1 = (h1 + (s[i] - seed + 1) * p_pow1) % mod1;
            h2 = (h2 + (s[i] - seed + 1) * p_pow2) % mod2;
            p_pow1 = (p_pow1 * p1) % mod1;
            p_pow2 = (p_pow2 * p2) % mod2;
            hash1[i] = h1;
            hash2[i] = h2;
        }
        hash_pair = make_pair(h1, h2);

        if(inv_size < length) {
            for(; inv_size < length; inv_size <<= 1);

            inv_pow1.resize(inv_size, -1);
            inv_pow2.resize(inv_size, -1);

            inv_pow1[inv_size - 1] = inverse(power(p1, inv_size - 1, mod1), mod1);
            inv_pow2[inv_size - 1] = inverse(power(p2, inv_size - 1, mod2), mod2);

            for(int i = inv_size - 2; i >= 0 && inv_pow1[i] == -1; i--) {
                inv_pow1[i] = (1LL * inv_pow1[i + 1] * p1) % mod1;
                inv_pow2[i] = (1LL * inv_pow2[i + 1] * p2) % mod2;
            }
        }
    }

    int size() {
        return length;
    }

    pair<int, int> prefix(const int index) {
        return {hash1[index], hash2[index]};
    }

    pair<int, int> substr(const int l, const int r) {
        if(l == 0) {
            return {hash1[r], hash2[r]};
        }
        int temp1 = hash1[r] - hash1[l - 1];
        int temp2 = hash2[r] - hash2[l - 1];
        temp1 += (temp1 < 0 ? mod1 : 0);
        temp2 += (temp2 < 0 ? mod2 : 0);
        temp1 = (temp1 * 1LL * inv_pow1[l]) % mod1;
        temp2 = (temp2 * 1LL * inv_pow2[l]) % mod2;
        return {temp1, temp2};
    }

    bool operator==(const Hash& other) {
        return (hash_pair == other.hash_pair);
    }
};

int longest_common_substring(const string& s1, const string& s2) {
    Hash h1(s1), h2(s2);
    const int m = s1.length(), n = s2.length();

    auto find = [&](int k) {
        set<pair<int, int>> substring_hashes;
        for(int begin = 0, end = begin + k - 1; end < n; begin++, end++) {
            substring_hashes.insert(h2.substr(begin, end));
        }
        for(int begin = 0, end = begin + k - 1; end < m; begin++, end++) {
            if(substring_hashes.count(h1.substr(begin, end))) {
                return true;
            }
        }
        return false;
    };

    int lcs_length = 0;
    int lb = 1, ub = min(m, n);
    while(lb <= ub) {
        int mid = (lb + ub) / 2;
        if(find(mid)) {
            lcs_length = mid;
            lb = mid + 1;
        } else {
            ub = mid - 1;
        }
    }

    return lcs_length;
}

// Big Integer for arbitrary 
// length integers

class big_integer {
public:
    short sign = 1;
    int length;
    string num;

    big_integer() {
        sign = 1;
        length = 0;
    }

    big_integer(const string& s) {
        length = s.length();
        assert(length > 0);
        if(s[0] == '-') {
            sign = -1;
            num = s.substr(1);
            length--;
        } else {
            sign = 1;
            num = s;
        }
        for(int i = 0; i < length; i++) {
            assert('0' <= num[i] && num[i] <= '9');
        }
        reverse(num.begin(), num.end());
        trim();
    }

    string to_string() {
        string res;
        if(sign == -1) {
            res.push_back('-');
        }
        for(int i = length - 1; i >= 0; i--) {
            res.push_back(num[i]);
        }
        return res;
    }

private:
    void trim() {
        while(length > 0 && num[length - 1] == '0') {
            length--;
            num.pop_back();
        }
        if(length == 0) {
            length++;
            num.push_back('0');
            sign = 1;
        }
    }

    bool lesser(const big_integer& a, const big_integer& b, const bool ignore_sign = false) const {
        if(a.length != b.length) {
            if(ignore_sign) {
                return a.length < b.length;
            }
            else {
                if(a.sign == 1 && b.sign == 1) {
                    return a.length < b.length;
                }
                else if(a.sign == -1 && b.sign == -1) {
                    return b.length < a.length;
                }
                else {
                    return a.sign == -1;
                }
            }
        }
        else {
            for(int i = a.length - 1; i >= 0; i--) {
                if(a.num[i] != b.num[i]) {
                    if(ignore_sign) {
                        return a.num[i] < b.num[i];
                    }
                    else {
                        if(a.sign == 1 && b.sign == 1) {
                            return a.num[i] < b.num[i];
                        }
                        else if(a.sign == -1 && b.sign == -1) {
                            return b.num[i] < a.num[i];
                        }
                        else {
                            return a.sign == -1;
                        }
                    }
                }
            }
            return false;
        }
    }

    bool greater(const big_integer& a, const big_integer& b, const bool ignore_sign = false) const {
        if(a.length != b.length) {
            if(ignore_sign) {
                return a.length > b.length;
            }
            else {
                if(a.sign == 1 && b.sign == 1) {
                    return a.length > b.length;
                }
                else if(a.sign == -1 && b.sign == -1) {
                    return b.length > a.length;
                }
                else {
                    return a.sign == 1;
                }
            }
        }
        else {
            for(int i = a.length - 1; i >= 0; i--) {
                if(a.num[i] != b.num[i]) {
                    if(ignore_sign) {
                        return a.num[i] > b.num[i];
                    }
                    else {
                        if(a.sign == 1 && b.sign == 1) {
                            return a.num[i] > b.num[i];
                        }
                        else if(a.sign == -1 && b.sign == -1) {
                            return b.num[i] > a.num[i];
                        }
                        else {
                            return a.sign == 1;
                        }
                    }
                }
            }
            return false;
        }
    }

    bool equals(const big_integer& a, const big_integer& b, const bool ignore_sign = false) const {
        return a.num == b.num && (ignore_sign ? true : a.sign == b.sign);
    }

public:
    bool operator ==(const big_integer& other) const {
        return equals(*this, other);
    }

    bool operator <(const big_integer& other) const {
        return lesser(*this, other);
    }

    bool operator >(const big_integer& other) const {
        return other < *this;
    }

    bool operator >=(const big_integer& other) const {
        return (*this > other || *this == other);
    }

    bool operator <=(const big_integer& other) const {
        return (*this < other || *this == other);
    }

    bool operator !=(const big_integer& other) const {
        return !(*this == other);
    }

private:
    big_integer add(const big_integer& a, const big_integer& b, short result_sign) const {
        big_integer res;
        int carry = 0;
        int i = 0;
        const int len1 = a.length, len2 = b.length;
        while(i < len1 || i < len2 || carry) {
            int sum = carry;
            if(i < len1) sum += a.num[i] - '0';
            if(i < len2) sum += b.num[i] - '0';
            res.num += (sum % 10) + '0';
            carry = sum / 10;
            i++;
        }
        res.sign = result_sign;
        res.length = res.num.size();
        res.trim();
        return res;
    }

    big_integer sub(const big_integer& a, const big_integer& b, short result_sign) const {
        big_integer res;
        int borrow = 0;
        int i = 0;
        const int len1 = a.length, len2 = b.length;
        while(i < len1 || i < len2 || borrow) {
            int diff = -borrow;
            if(i < len1) diff += a.num[i] - '0';
            if(i < len2) diff -= b.num[i] - '0';
            if(diff < 0) {
                diff += 10;
                borrow = 1;
            }
            else {
                borrow = 0;
            }
            res.num += (diff % 10) + '0';
            i++;
        }
        res.sign = result_sign;
        res.length = res.num.size();
        res.trim();
        return res;
    }

    big_integer mul(const int x) const {
        assert(0 <= x && x <= 9);
        big_integer res;
        int carry = 0;
        for(int i = 0; i < length; i++) {
            int cur = (num[i] - '0') * x + carry;
            res.num += (cur % 10) + '0';
            carry = cur / 10;
        }
        if(carry) res.num += carry + '0';
        res.sign = 1;
        res.length = res.num.size();
        res.trim();
        return res;
    }

    big_integer div(const big_integer& other) const {
        assert(other != big_integer("0"));
        auto half = [&](big_integer& a) {
            a.num[0] -= (a.num[0] - '0') & 1;
            int dividend = 0;
            string result;
            for(int i = a.length - 1; i >= 0; i--) {
                dividend = (dividend * 10) + (a.num[i] - '0');
                if(dividend == 1) {
                    if(i != a.length - 1) {
                        result.push_back('0');
                    }
                    continue;
                }
                result.push_back(dividend / 2 + '0');
                dividend %= 2;
            }
            reverse(result.begin(), result.end());
            if(result == "") {
                a.num = "0";
            }
            else {
                a.num = result;
            }
            a.length = a.num.size();
            a.trim();
        };
        big_integer lb("0"), ub(*this);
        lb.sign = 1, ub.sign = 1;
        big_integer result;
        while(lb <= ub) {
            big_integer mid = (lb + ub);
            half(mid);
            big_integer product = other * mid;
            if(lesser(product, *this, true) || equals(product, *this, true)) {
                result = mid;
                lb = mid + big_integer("1");
            }
            else {
                ub = mid - big_integer("1");
            }
        }
        result.length = result.num.size();
        result.trim();
        result.sign = (result == big_integer("0") ? 1 : this->sign * other.sign);
        return result;
    }

public:
    big_integer operator+(const big_integer& other) const {
        if(sign * other.sign == 1) {
            return add(*this, other, this -> sign);
        }
        else {
            if(this -> sign == -1) {
                if(lesser(*this, other, true)) {
                    return sub(other, *this, 1);
                }
                else if(greater(*this, other, true)) {
                    return sub(*this, other, -1);
                }
                else {
                    return big_integer("0");
                }
            }
            else {
                if(lesser(*this, other, true)) {
                    return sub(other, *this, -1);
                }
                else if(greater(*this, other, true)) {
                    return sub(*this, other, 1);
                }
                else {
                    return big_integer("0");
                }
            }
        }
    }

    big_integer operator-(const big_integer& other) const {
        if(sign * other.sign == -1) {
            return add(*this, other, this -> sign);
        }
        else {
            if(this -> sign == -1) {
                if(lesser(*this, other, true)) {
                    return sub(other, *this, 1);
                }
                else if(greater(*this, other, true)) {
                    return sub(*this, other, -1);
                }
                else {
                    return big_integer("0");
                }
            }
            else {
                if(lesser(*this, other, true)) {
                    return sub(other, *this, -1);
                }
                else if(greater(*this, other, true)) {
                    return sub(*this, other, 1);
                }
                else {
                    return big_integer("0");
                }
            }
        }
    }

    big_integer operator*(const big_integer& other) const {
        string prods[10];
        for(int i = 0; i < 10; i++) {
            prods[i] = mul(i).num;
            reverse(prods[i].begin(), prods[i].end());
        }

        const int len2 = other.length;

        string zeroes;
        big_integer res;

        for(int i = 0; i < len2; i++) {
            string curr_prod = prods[other.num[i] - '0'];
            curr_prod += zeroes;
            res = add(res, curr_prod, 1);
            zeroes += '0';
        }

        res.sign = sign * other.sign;
        res.length = res.num.size();
        res.trim();
        return res;
    }

    big_integer operator/(const big_integer& other) {
        return div(other);
    }

    big_integer operator%(const big_integer& other) {
        big_integer quotient = *(this) / other;
        big_integer product = quotient * other;
        big_integer remainder = *this - product;
        return remainder;
    }

    void operator+=(const big_integer& other) {
        *this = *this + other;
    }

    void operator-=(const big_integer& other) {
        *this = *this - other;
    }

    void operator*=(const big_integer& other) {
        *this = *this * other;
    }

    void operator/=(const big_integer& other) {
        *this = *this / other;
    }

    void operator%=(const big_integer& other) {
        *this = *this % other;
    }

    ~big_integer() {
        this -> num.clear();
        this -> sign = 1;
        this -> length = 0;
    }
};

ostream& operator<<(ostream& out, const big_integer& a) {
    if(a.sign == -1) {
        out << "-";
    }
    for(int i = a.length - 1; i >= 0; i--) {
        out << a.num[i];
    }
    return out;
}

// Ordered Multiset (allows Duplicates)
// Code Penned via standard programming aids
// Supports O(log N) insertion, removal and access
// Keeps the elements ordered
template <typename T>
class ordered_multiset {
private:
    enum Color { RED, BLACK };

    struct Node {
        T key;
        Node* parent;
        Node* left;
        Node* right;
        Color color;
        int size;
    };

    Node* root;

    Node* createNode(const T& key) {
        Node* newNode = new Node;
        newNode->key = key;
        newNode->parent = nullptr;
        newNode->left = nullptr;
        newNode->right = nullptr;
        newNode->color = RED;
        newNode->size = 1;
        return newNode;
    }

    void updateSize(Node* node) {
        if (node != nullptr) {
            int leftSize = (node->left != nullptr) ? node->left->size : 0;
            int rightSize = (node->right != nullptr) ? node->right->size : 0;
            node->size = leftSize + rightSize + 1;
        }
    }

    void rotateLeft(Node* x) {
        Node* y = x->right;
        x->right = y->left;
        if (y->left != nullptr)
            y->left->parent = x;
        y->parent = x->parent;
        if (x->parent == nullptr)
            root = y;
        else if (x == x->parent->left)
            x->parent->left = y;
        else
            x->parent->right = y;
        y->left = x;
        x->parent = y;

        updateSize(x);
        updateSize(y);
    }

    void rotateRight(Node* x) {
        Node* y = x->left;
        x->left = y->right;
        if (y->right != nullptr)
            y->right->parent = x;
        y->parent = x->parent;
        if (x->parent == nullptr)
            root = y;
        else if (x == x->parent->right)
            x->parent->right = y;
        else
            x->parent->left = y;
        y->right = x;
        x->parent = y;

        updateSize(x);
        updateSize(y);
    }

    void fixInsertion(Node* z) {
        while (z->parent != nullptr && z->parent->color == RED) {
            if (z->parent == z->parent->parent->left) {
                Node* y = z->parent->parent->right;
                if (y != nullptr && y->color == RED) {
                    z->parent->color = BLACK;
                    y->color = BLACK;
                    z->parent->parent->color = RED;
                    z = z->parent->parent;
                } else {
                    if (z == z->parent->right) {
                        z = z->parent;
                        rotateLeft(z);
                    }
                    z->parent->color = BLACK;
                    z->parent->parent->color = RED;
                    rotateRight(z->parent->parent);
                }
            } else {
                Node* y = z->parent->parent->left;
                if (y != nullptr && y->color == RED) {
                    z->parent->color = BLACK;
                    y->color = BLACK;
                    z->parent->parent->color = RED;
                    z = z->parent->parent;
                } else {
                    if (z == z->parent->left) {
                        z = z->parent;
                        rotateRight(z);
                    }
                    z->parent->color = BLACK;
                    z->parent->parent->color = RED;
                    rotateLeft(z->parent->parent);
                }
            }
        }
        root->color = BLACK;
    }

    void transplant(Node* u, Node* v) {
        if (u->parent == nullptr)
            root = v;
        else if (u == u->parent->left)
            u->parent->left = v;
        else
            u->parent->right = v;
        if (v != nullptr)
            v->parent = u->parent;
    }

    Node* treeMinimum(Node* x) {
        while (x->left != nullptr)
            x = x->left;
        return x;
    }

    void fixDeletion(Node* x) {
        while (x != root && x->color == BLACK) {
            if (x == x->parent->left) {
                Node* w = x->parent->right;
                if (w->color == RED) {
                    w->color = BLACK;
                    x->parent->color = RED;
                    rotateLeft(x->parent);
                    w = x->parent->right;
                }
                if (w->left->color == BLACK && w->right->color == BLACK) {
                    w->color = RED;
                    x = x->parent;
                } else {
                    if (w->right->color == BLACK) {
                        w->left->color = BLACK;
                        w->color = RED;
                        rotateRight(w);
                        w = x->parent->right;
                    }
                    w->color = x->parent->color;
                    x->parent->color = BLACK;
                    w->right->color = BLACK;
                    rotateLeft(x->parent);
                    x = root;
                }
            } else {
                Node* w = x->parent->left;
                if (w->color == RED) {
                    w->color = BLACK;
                    x->parent->color = RED;
                    rotateRight(x->parent);
                    w = x->parent->left;
                }
                if (w->right->color == BLACK && w->left->color == BLACK) {
                    w->color = RED;
                    x = x->parent;
                } else {
                    if (w->left->color == BLACK) {
                        w->right->color = BLACK;
                        w->color = RED;
                        rotateLeft(w);
                        w = x->parent->left;
                    }
                    w->color = x->parent->color;
                    x->parent->color = BLACK;
                    w->left->color = BLACK;
                    rotateRight(x->parent);
                    x = root;
                }
            }
        }
        x->color = BLACK;
    }

    Node* findNode(const T& key) const {
        Node* current = root;
        while (current != nullptr) {
            if (key == current->key)
                return current;
            else if (key < current->key)
                current = current->left;
            else
                current = current->right;
        }
        return nullptr;
    }

    Node* getNodeAtIndex(Node* x, int index) {
        if (x == nullptr)
            return nullptr;

        int leftSize = (x->left != nullptr) ? x->left->size : 0;

        if (index < leftSize)
            return getNodeAtIndex(x->left, index);
        else if (index == leftSize)
            return x;
        else
            return getNodeAtIndex(x->right, index - leftSize - 1);
    }

public:
    RedBlackTree() : root(nullptr) {}

    int insert(const T& key) {
        Node* z = createNode(key);
        Node* y = nullptr;
        Node* x = root;
        while (x != nullptr) {
            y = x;
            x->size++;
            if (z->key < x->key)
                x = x->left;
            else
                x = x->right;
        }
        z->parent = y;
        if (y == nullptr)
            root = z;
        else if (z->key < y->key)
            y->left = z;
        else
            y->right = z;
        fixInsertion(z);
        return 0;
    }

    void erase(const T& key) {
        Node* z = findNode(key);
        if (z == nullptr)
            return;
        Node* y = z;
        Node* x = nullptr;
        Color yOriginalColor = y->color;
        if (z->left == nullptr) {
            x = z->right;
            transplant(z, z->right);
        } else if (z->right == nullptr) {
            x = z->left;
            transplant(z, z->left);
        } else {
            y = treeMinimum(z->right);
            yOriginalColor = y->color;
            x = y->right;
            if (y->parent == z)
                x->parent = y;
            else {
                transplant(y, y->right);
                y->right = z->right;
                y->right->parent = y;
            }
            transplant(z, y);
            y->left = z->left;
            y->left->parent = y;
            y->color = z->color;
        }
        delete z;

        Node* current = x;
        while (current != nullptr) {
            updateSize(current);
            current = current->parent;
        }

        if (yOriginalColor == BLACK)
            fixDeletion(x);
    }

    const T& getElementAt(int index) {
        Node* nodeAtIndex = getNodeAtIndex(root, index);
        if (nodeAtIndex == nullptr) {
            throw std::out_of_range("Index out of range");
        }
        return nodeAtIndex->key;
    }

    int getIndex(const T& key) const {
        int index = 0;
        Node* current = root;
        while (current != nullptr) {
            if (key == current->key)
                return index + (current->left != nullptr ? current->left->size : 0);
            else if (key < current->key)
                current = current->left;
            else {
                index += (current->left != nullptr ? current->left->size : 0) + 1;
                current = current->right;
            }
        }
        throw std::out_of_range("Element not found");
    }
};

// Ordered multi_set using GNU PBDS
// Allows duplicates
// Include these headers
// #include <ext/pb_ds/assoc_container.hpp>
// #include <ext/pb_ds/tree_policy.hpp>
// using namespace __gnu_pbds;
template<typename T>
class Ordered_Multiset_PBDS {
private:
    int unique_id = 0;
    tree<pair<T, int>, null_type, less<pair<T, int>>, rb_tree_tag, tree_order_statistics_node_update> my_tree;
public:
    void insert(T item) {
        my_tree.insert({item, unique_id++});
    }

    void erase(T item) {
        my_tree.erase({item, 0});
    }

    T get_element_at(int index) {
        return (*my_tree.find_by_order(index)).first;
    }

    int count_less_than(T item) {
        return int(my_tree.order_of_key({item, 0}));
    }

    int size() {
        return my_tree.size();
    }
};

// Ordered set (does not allow duplicates)
// Code Penned via standard programming aids
// Supports O(log N) insertion, removal and access
// Keeps the elements ordered
template <typename T>
class ordered_set {
private:
    set<T> tracker;
    enum Color { RED, BLACK };

    struct Node {
        T key;
        Node* parent;
        Node* left;
        Node* right;
        Color color;
        int size;
    };

    Node* root;

    Node* createNode(const T& key) {
        Node* newNode = new Node;
        newNode->key = key;
        newNode->parent = nullptr;
        newNode->left = nullptr;
        newNode->right = nullptr;
        newNode->color = RED;
        newNode->size = 1;
        return newNode;
    }

    void updateSize(Node* node) {
        if (node != nullptr) {
            int leftSize = (node->left != nullptr) ? node->left->size : 0;
            int rightSize = (node->right != nullptr) ? node->right->size : 0;
            node->size = leftSize + rightSize + 1;
        }
    }

    void rotateLeft(Node* x) {
        Node* y = x->right;
        x->right = y->left;
        if (y->left != nullptr)
            y->left->parent = x;
        y->parent = x->parent;
        if (x->parent == nullptr)
            root = y;
        else if (x == x->parent->left)
            x->parent->left = y;
        else
            x->parent->right = y;
        y->left = x;
        x->parent = y;

        updateSize(x);
        updateSize(y);
    }

    void rotateRight(Node* x) {
        Node* y = x->left;
        x->left = y->right;
        if (y->right != nullptr)
            y->right->parent = x;
        y->parent = x->parent;
        if (x->parent == nullptr)
            root = y;
        else if (x == x->parent->right)
            x->parent->right = y;
        else
            x->parent->left = y;
        y->right = x;
        x->parent = y;

        updateSize(x);
        updateSize(y);
    }

    void fixInsertion(Node* z) {
        while (z->parent != nullptr && z->parent->color == RED) {
            if (z->parent == z->parent->parent->left) {
                Node* y = z->parent->parent->right;
                if (y != nullptr && y->color == RED) {
                    z->parent->color = BLACK;
                    y->color = BLACK;
                    z->parent->parent->color = RED;
                    z = z->parent->parent;
                } else {
                    if (z == z->parent->right) {
                        z = z->parent;
                        rotateLeft(z);
                    }
                    z->parent->color = BLACK;
                    z->parent->parent->color = RED;
                    rotateRight(z->parent->parent);
                }
            } else {
                Node* y = z->parent->parent->left;
                if (y != nullptr && y->color == RED) {
                    z->parent->color = BLACK;
                    y->color = BLACK;
                    z->parent->parent->color = RED;
                    z = z->parent->parent;
                } else {
                    if (z == z->parent->left) {
                        z = z->parent;
                        rotateRight(z);
                    }
                    z->parent->color = BLACK;
                    z->parent->parent->color = RED;
                    rotateLeft(z->parent->parent);
                }
            }
        }
        root->color = BLACK;
    }

    void transplant(Node* u, Node* v) {
        if (u->parent == nullptr)
            root = v;
        else if (u == u->parent->left)
            u->parent->left = v;
        else
            u->parent->right = v;
        if (v != nullptr)
            v->parent = u->parent;
    }

    Node* treeMinimum(Node* x) {
        while (x->left != nullptr)
            x = x->left;
        return x;
    }

    void fixDeletion(Node* x) {
        while (x != root && x->color == BLACK) {
            if (x == x->parent->left) {
                Node* w = x->parent->right;
                if (w->color == RED) {
                    w->color = BLACK;
                    x->parent->color = RED;
                    rotateLeft(x->parent);
                    w = x->parent->right;
                }
                if (w->left->color == BLACK && w->right->color == BLACK) {
                    w->color = RED;
                    x = x->parent;
                } else {
                    if (w->right->color == BLACK) {
                        w->left->color = BLACK;
                        w->color = RED;
                        rotateRight(w);
                        w = x->parent->right;
                    }
                    w->color = x->parent->color;
                    x->parent->color = BLACK;
                    w->right->color = BLACK;
                    rotateLeft(x->parent);
                    x = root;
                }
            } else {
                Node* w = x->parent->left;
                if (w->color == RED) {
                    w->color = BLACK;
                    x->parent->color = RED;
                    rotateRight(x->parent);
                    w = x->parent->left;
                }
                if (w->right->color == BLACK && w->left->color == BLACK) {
                    w->color = RED;
                    x = x->parent;
                } else {
                    if (w->left->color == BLACK) {
                        w->right->color = BLACK;
                        w->color = RED;
                        rotateLeft(w);
                        w = x->parent->left;
                    }
                    w->color = x->parent->color;
                    x->parent->color = BLACK;
                    w->left->color = BLACK;
                    rotateRight(x->parent);
                    x = root;
                }
            }
        }
        x->color = BLACK;
    }

    Node* findNode(const T& key) const {
        Node* current = root;
        while (current != nullptr) {
            if (key == current->key)
                return current;
            else if (key < current->key)
                current = current->left;
            else
                current = current->right;
        }
        return nullptr;
    }

    Node* getNodeAtIndex(Node* x, int index) {
        if (x == nullptr)
            return nullptr;

        int leftSize = (x->left != nullptr) ? x->left->size : 0;

        if (index < leftSize)
            return getNodeAtIndex(x->left, index);
        else if (index == leftSize)
            return x;
        else
            return getNodeAtIndex(x->right, index - leftSize - 1);
    }

public:
    RedBlackTree() : root(nullptr) {}

    int insert(const T& key) {
        if (!(tracker.find(key) == tracker.end())) {
            return;
        }
        tracker.insert(key);
        Node* z = createNode(key);
        Node* y = nullptr;
        Node* x = root;
        while (x != nullptr) {
            y = x;
            x->size++;
            if (z->key < x->key)
                x = x->left;
            else
                x = x->right;
        }
        z->parent = y;
        if (y == nullptr)
            root = z;
        else if (z->key < y->key)
            y->left = z;
        else
            y->right = z;
        fixInsertion(z);
        return 0;
    }

    void erase(const T& key) {
        tracker.erase(key);
        Node* z = findNode(key);
        if (z == nullptr)
            return;
        Node* y = z;
        Node* x = nullptr;
        Color yOriginalColor = y->color;
        if (z->left == nullptr) {
            x = z->right;
            transplant(z, z->right);
        } else if (z->right == nullptr) {
            x = z->left;
            transplant(z, z->left);
        } else {
            y = treeMinimum(z->right);
            yOriginalColor = y->color;
            x = y->right;
            if (y->parent == z)
                x->parent = y;
            else {
                transplant(y, y->right);
                y->right = z->right;
                y->right->parent = y;
            }
            transplant(z, y);
            y->left = z->left;
            y->left->parent = y;
            y->color = z->color;
        }
        delete z;

        Node* current = x;
        while (current != nullptr) {
            updateSize(current);
            current = current->parent;
        }

        if (yOriginalColor == BLACK)
            fixDeletion(x);
    }

    const T& getElementAt(int index) {
        Node* nodeAtIndex = getNodeAtIndex(root, index);
        if (nodeAtIndex == nullptr) {
            throw std::out_of_range("Index out of range");
        }
        return nodeAtIndex->key;
    }

    int getIndex(const T& key) const {
        int index = 0;
        Node* current = root;
        while (current != nullptr) {
            if (key == current->key)
                return index + (current->left != nullptr ? current->left->size : 0);
            else if (key < current->key)
                current = current->left;
            else {
                index += (current->left != nullptr ? current->left->size : 0) + 1;
                current = current->right;
            }
        }
        throw std::out_of_range("Element not found");
    }
};

// Ordered Set using GNU PBDS
