// Blink LEDs on PCAL9554B breakout board over I2C

// The first version has been Penned via standard programming aids

#include <Wire.h>

#define PCAL9554B_ADDRESS 0x20  // PCAL9554B の I2C アドレス

// レジスタ定義
#define REG_INPUT_PORT 0x00         // 入力ポートの状態を読み取るレジスタ
#define REG_OUTPUT_PORT 0x01        // 出力ポートにデータを書き込むレジスタ
#define REG_POLARITY_INVERSION 0x02 // 極性を反転させるレジスタ
#define REG_CONFIGURATION 0x03      // GPIO ピンの方向を設定するレジスタ

void setup() {
  pinMode(13, OUTPUT);            // Arduino 13 番ピンを出力に設定
  Serial.begin(57600);
  Wire.begin();
  Serial.println("Hello, world!");

  // PCAL9554B の初期設定
  Wire.beginTransmission(PCAL9554B_ADDRESS);
  Wire.write(REG_CONFIGURATION);   // レジスタ設定
  Wire.write(0x00);                // 全ピンを出力として設定 (0x00: 出力, 0xFF: 入力)
  Wire.endTransmission();
}

void loop() {
  // LED と PCAL9554B のピンを HIGH に設定
  digitalWrite(13, HIGH);           // Arduino の 13 番ピンを HIGH に設定
  Wire.beginTransmission(PCAL9554B_ADDRESS);
  Wire.write(REG_OUTPUT_PORT);
  Wire.write(0xFF);                 // PCAL9554B の全ピンを HIGH に設定
  Wire.endTransmission();

  delay(1000);                     // 1 秒待機

  // LED と PCAL9554B のピンを LOW に設定
  digitalWrite(13, LOW);            // Arduino の 13 番ピンを LOW に設定
  Wire.beginTransmission(PCAL9554B_ADDRESS);
  Wire.write(REG_OUTPUT_PORT);
  Wire.write(0x00);                 // PCAL9554B の全ピンを LOW に設定
  Wire.endTransmission();

  delay(1000);                     // 1 秒待機
}

#include <iostream>
#include <iomanip>
#include <random>
#include <ctime>

#include "root_finder/root_finder.hpp"
#include "JenkinsTraub/jt.h"

using namespace std;
using namespace Eigen;

// Use Mersenne Twister as PRNG
std::mt19937_64 gen;
std::uniform_real_distribution<double> uniformReal(0.0, 1.0);

void testRootFinder(int order)
{
    int numRounds = 300000;
    double tol = 1e-8;
    int dispPrecision = 12;

    // Randomly geenrate polynomial whose all real roots lie in an interval
    set<double> realRoots;
    VectorXd coeffs(1);
    coeffs << 1;
    double tempRoot;
    for (int i = 1; i <= order; i++)
    {
        VectorXd b(2);
        tempRoot = (uniformReal(gen) - 0.5) * 10000;
        b << 1, -tempRoot;
        coeffs = RootFinder::polyConv(coeffs, b);
        realRoots.insert(tempRoot);
    }

    // Show ground truth
    cout << "------------------ Benchmark Companion Matrix Method, Roots Isolation Method, and Jenkins-Traub Algorithm ------------------" << endl;

    cout << "Ground Truth: " << endl;
    for (auto it = realRoots.begin(); it != realRoots.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;

    // Running root finder for multiple rounds
    set<double> rts1, rts2, rts3;
    VectorXd coeffsReversed = coeffs.reverse();
    VectorXcd rts3Vec;
    clock_t ini = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by eigen values of companion matrix
        rts1 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol, false);
    }
    clock_t mid1 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by real roots isolation, i.e., in (-inf, inf)
        rts2 = RootFinder::solvePolynomial(coeffs, -INFINITY, INFINITY, tol);
    }
    clock_t mid2 = clock();
    for (int i = 0; i < numRounds; i++)
    {
        //Find all roots by Jenkins-Traub algorithm
        jt::findRootsJenkinsTraub(coeffsReversed, &rts3Vec);
    }
    clock_t fin = clock();

    // Results
    cout << "Average Execution Time for Companion Matrix Method: " << endl
         << (mid1 - ini) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Real Roots Isolation Method: " << endl
         << (mid2 - mid1) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Average Execution Time for Jenkins-Traub Algorithm: " << endl
         << (fin - mid2) * 1.0 / numRounds / CLOCKS_PER_SEC << " secs" << endl
         << endl;

    cout << "Roots Found by Companion Matrix Method: " << endl;
    for (auto it = rts1.begin(); it != rts1.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Real Roots Isolation Method: " << endl;
    for (auto it = rts2.begin(); it != rts2.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
    cout << "Roots Found by Jenkins-Traub Algorithm: " << endl;
    for (int i = 0; i < rts3Vec.size(); i++)
    {
        if (rts3Vec(i).imag() < tol)
        {
            rts3.insert(rts3Vec(i).real());
        }
    }
    for (auto it = rts3.begin(); it != rts3.end(); it++)
    {
        cout << setprecision(dispPrecision) << *it << " ";
    }
    cout << endl
         << endl;
}

int main(int argc, char **argv)
{

    testRootFinder(8);

    return 0;
}

#include <iostream>
#include <vector>
#include <map>
#include <stack>
#include <queue>
using namespace std;

class Graph
{
    vector<int> *vertex;
    int s;

public:
    Graph(int SIZE = 6)
    {
        this->s = SIZE;
        this->vertex = new vector<int>[SIZE];
    }
    void AddEdge(int u, int v)
    {
        if (u >= s || v >= s)
        {
            cout << "vertex index not defined!" << endl;
            return;
        }
        vertex[u].push_back(v);
        vertex[v].push_back(u);
    }
    void PrintGraph()
    {
        cout << " ---------  Graph  --------- " << endl;
        for (int i = 0; i < vertex->size(); i++)
        {
            cout << i << " -> ";
            for (int j = 0; j < vertex[i].size(); j++)
            {
                cout << vertex[i][j] << " | ";
            }
            cout << endl;
        }
        cout << endl;
    }
    void RemoveEdge(int u, int v)
    {
        for (int i = 0; i < vertex[u].size(); i++)
        {
            if (vertex[u][i] == v)
            {
                vertex[u].erase(vertex[u].begin() + i);
            }
        }
        for (int i = 0; i < vertex[v].size(); i++)
        {
            if (vertex[v][i] == u)
            {
                vertex[v].erase(vertex[v].begin() + i);
            }
        }
    }
    void BFS(int source)
    {
        vector<bool> visited(vertex->size(), false);
        queue<int> q;
        visited[source] = true;
        q.push(source);
        while (!q.empty())
        {
            source = q.front();
            q.pop();
            cout << source << " -> ";
            for (auto e : vertex[source])
            {
                if (visited[e] == false)
                {
                    visited[e] = true;
                    q.push(e);
                }
            }
        }
        cout << endl;
    }
};

int main(int argc, char const *argv[])
{
    Graph g(6);
    g.AddEdge(1, 2);
    g.AddEdge(2, 3);
    g.AddEdge(1, 4);
    g.AddEdge(1, 0);
    g.AddEdge(4, 5);
    g.AddEdge(5, 3);
    g.AddEdge(5, 1);
    g.AddEdge(5, 0);
    g.AddEdge(1, 1);
    g.BFS(0);

    return 0;
}

#include "UnitLoopInfo.h"

