#include "Database.h"

/**
 * Initialize vignette model with some vignetting
 */
Database::Database(int image_width,int image_height) :
    m_vignette_estimate(-0.3,0,0,image_width,image_height),
    m_response_estimate()
{
    m_image_width  = image_width;
    m_image_height = image_height;
}

void Database::visualizeTracking()
{
    // Fetch tracking information and create a canvas
    Frame last_frame = m_tracked_frames.at(m_tracked_frames.size()-1);
    // Todo: change to class member
    cv::Mat draw_image = last_frame.m_image.clone();

    // Draw features on the canvas
    for(int i = 0;i < last_frame.m_features.size();i++)
    {
        cv::circle(draw_image, last_frame.m_features.at(i)->m_xy_location, 3, cv::Scalar(255,0,0));
    }

    // Correct the frame based on the current estimate
    // Todo: change to class member
    cv::Mat corrected_frame = last_frame.m_image.clone();

    for(int r = 0; r < corrected_frame.rows;r++)
    {
        for(int c = 0;c < corrected_frame.cols;c++)
        {
            // Apply rsponse and vignette for each pixel
            int o_value = corrected_frame.at<uchar>(r,c);
            double new_o_value = m_response_estimate.removeResponse(o_value);

            double v_factor = m_vignette_estimate.getVignetteFactor(cv::Point2f(c,r));
            new_o_value /= v_factor;

            // Correct by exposure time
            new_o_value /= last_frame.m_exp_time;
            if(new_o_value > 255)new_o_value = 255; 
            corrected_frame.at<uchar>(r,c) = (uchar)new_o_value;
        }
    }

    //resize drawing images to an acceptable size
    int image_width  = 640;
    int image_height = 480;

    cv::resize(draw_image, draw_image, cv::Size(image_width,image_height));
    cv::resize(corrected_frame, corrected_frame, cv::Size(image_width,image_height));

    // Display
    cv::imshow("Tracked frame", draw_image);
    cv::imshow("Corrected frame", corrected_frame);
    cv::waitKey(1);
}

void Database::visualizeRapidExposureTimeEstimates(double exponent)
{
    // Visualize exposure times 
    // If GT data is available, the estimated exposure times will be aligned 
    // to the GT by computing an optimal alignment factor alignment_alpha
    // If no GT data is available, the estimated exposure is simply scaled between [0,1]
    int nr_frames_to_vis = int(fmin(m_tracked_frames.size(),40));
    int exp_image_height = 150;
    int draw_spacing = 8;
    std::vector<double> estimated_exp_times;
    std::vector<double> gt_exp_times;
    double alignment_alpha = 1.0;
    double max_exp = -10000.0;
    double min_exp = 10000.0;
    double top = 0;
    double bot = 0;
    for(int i = 0;i < nr_frames_to_vis;i++)
    {
        // Fetch estimated and GT exposure time data, pow estimates with alignment exponent
        Frame current_frame = m_tracked_frames.at(m_tracked_frames.size()-nr_frames_to_vis+i);
        double frame_exp_time = pow(current_frame.m_exp_time,exponent);
        double frame_time_gt  = current_frame.m_gt_exp_time;

        // Keep track of max and min exposure to scale between [0,1]
        if(frame_exp_time > max_exp)
            max_exp = frame_exp_time;
        if(frame_exp_time < min_exp)
            min_exp = frame_exp_time;

        // Accumulate information for least square fit between GT and estimated exposure
        top += frame_exp_time*frame_time_gt;
        bot += frame_exp_time*frame_exp_time;

        // Push back estimated exposure values
        estimated_exp_times.push_back(frame_exp_time);

        // Push gt exposure time if available
        if(!(frame_time_gt < 0))
            gt_exp_times.push_back(frame_time_gt);
    }

    // Set alignment factor only if GT exposure is available
    if(gt_exp_times.size() == estimated_exp_times.size())
        alignment_alpha = top/bot;
    else
    {
        // Normalize estimated exposures between [0,1]
        for(int k = 0;k < estimated_exp_times.size();k++)
        {
            estimated_exp_times.at(k) = (estimated_exp_times.at(k)-min_exp)/(max_exp-min_exp);
        }
    }

    // Create exposure time canvas
    cv::Mat exposure_vis_image(exp_image_height,draw_spacing*nr_frames_to_vis,CV_8UC3,cv::Scalar(0,0,0));

    // Draw estimated exposure times as lines to graph
    for(int i = 0;i < nr_frames_to_vis-1;i++)
    {
        int drawing_y_exp_1 = exp_image_height - exp_image_height*(alignment_alpha * estimated_exp_times.at(i));
        drawing_y_exp_1 = int(fmax(0,drawing_y_exp_1));
        drawing_y_exp_1 = int(fmin(exp_image_height-1,drawing_y_exp_1));

        int drawing_y_exp_2 = exp_image_height - exp_image_height*(alignment_alpha * estimated_exp_times.at(i+1));
        drawing_y_exp_2 = int(fmax(0,drawing_y_exp_2));
        drawing_y_exp_2 = int(fmin(exp_image_height-1,drawing_y_exp_2));

        // Draw exposure lines
        cv::line(exposure_vis_image, cv::Point(draw_spacing*i,drawing_y_exp_1), cv::Point(draw_spacing*(i+1),drawing_y_exp_2), cv::Scalar(0,0,255));
     }

    // Draw GT exposure line only if GT exposure data is available
    if(gt_exp_times.size() == estimated_exp_times.size())
    {
        for(int i = 0;i < nr_frames_to_vis-1;i++)
        {
            int drawing_y_gt_exp_1 = exp_image_height - exp_image_height * gt_exp_times.at(i);
            drawing_y_gt_exp_1 = int(fmax(0,drawing_y_gt_exp_1));
            drawing_y_gt_exp_1 = int(fmin(exp_image_height-1,drawing_y_gt_exp_1));

            int drawing_y_gt_exp_2 = exp_image_height - exp_image_height * gt_exp_times.at(i+1);
            drawing_y_gt_exp_2 = int(fmax(0,drawing_y_gt_exp_2));
            drawing_y_gt_exp_2 = int(fmin(exp_image_height-1,drawing_y_gt_exp_2));

            cv::line(exposure_vis_image, cv::Point(draw_spacing*i,drawing_y_gt_exp_1), cv::Point(draw_spacing*(i+1),drawing_y_gt_exp_2), cv::Scalar(255,255,0));
        }
    }   

    cv::imshow("Estimated Exposure (Rapid)", exposure_vis_image);
    cv::moveWindow("Estimated Exposure (Rapid)", 20+20+256,20);

}

// Todo: change the return to parameter passed by reference
std::vector<cv::Point2f> Database::fetchActiveFeatureLocations()
{
    std::vector<cv::Point2f> point_locations;

    Frame last_frame = m_tracked_frames.at(m_tracked_frames.size()-1);

    for(int i = 0;i < last_frame.m_features.size();i++)
    {
        point_locations.push_back(last_frame.m_features.at(i)->m_xy_location);
    }

    return point_locations;
}

void Database::removeLastFrame()
{
    // Erase the information about the first frame
    m_tracked_frames.erase(m_tracked_frames.begin());

    // Let all pointers of the new first frame point to NULL
    for(int i = 0;i < m_tracked_frames.at(0).m_features.size();i++)
    {
        m_tracked_frames.at(0).m_features.at(i)->m_prev_feature = NULL;
    }
}

#include <regex>
#include "web_server.h"
bool VERBOSE;


// **************************************************************************************
// * processConnection()
// * - Handles reading the line from the network and sending it back to the client.
// * - Returns true if the client sends "QUIT" command, false if the client sends "CLOSE".
// **************************************************************************************
#define BUFFER_SIZE 1024

// **************************************************************************************
// * Read the header. Return the appropriate status code and filename
// **************************************************************************************

int readRequest(int connFd, std::string& filename) {
	int returnCode = 400; //Default return code

	//read everything up to and including end of the header:
	std::string requestHeader;
	char buffer[BUFFER_SIZE];
	ssize_t bytesRead;

	while(true) {
		bytesRead = read(connFd, buffer, sizeof(buffer));

		//check if there is a client connection
		if (bytesRead <= 0) {
			return returnCode;
		}

		//append the data from client to requestHeader
		requestHeader.append(buffer, bytesRead);

		//this will check if the end of requestHeader is reached
		size_t endOfHeader = requestHeader.find("\r\n\r\n");
		if (endOfHeader != std::string::npos) {
			break;
		}
	}

	//output the request header
	if (VERBOSE) {
		std::cout << "----------------------- Start of header ----------------------" << std::endl;
		std::cout << requestHeader << std::endl;
		std::cout << "----------------------- End of header ------------------------" << std::endl;
	}

	//split header into different lines
	std::istringstream headerStream(requestHeader);
	std::string line;

	//Look at the first line of the header
	if (std::getline(headerStream, line)) {
		//check for valid GET
		if (line.find("GET ") == 0) {
			//find the filename
			size_t firstSpaceIndex = line.find(' ', 4);
			if (firstSpaceIndex != std::string::npos) {
				std::string requestedFile = line.substr(4, firstSpaceIndex - 4);

				//check for valid filename
				if (std::regex_match(requestedFile, std::regex("^/(file[0-9].html|image[0-9].jpg)$"))) {
					returnCode = 200; //if filename is valid, set return code to 200
					filename = requestedFile.substr(1);
				} else {
					returnCode = 404; //if filename is invalid, set return code to 404

				}
			}
		}
	}

	return returnCode;
}
//The above section of the code is base on assistance Adapted from standard coding samples, a language model by OpenAI.
//Reference: https://openai.com/chatgpt

int sendLine(int connFd, const std::string& stringToSend) {
	char buffer[stringToSend.size() + 2]; //char array that is 2 bytes longer than the string

	//copy string to bugger
	std::copy(stringToSend.begin(), stringToSend.end(), buffer);

	//replace the last two bytes of the array with the <CR> and <LF>
	buffer[stringToSend.size()] = '\r';
	buffer[stringToSend.size() + 1] = '\n';

	//call write function to send that array
	ssize_t bytesWritten = write(connFd, buffer, sizeof(buffer));

	//check for errors
	if (bytesWritten == -1) {
		return -1;
	} else if (bytesWritten != sizeof(buffer)) {
		return -2;
	}

	return 0;
}

int send404(int connFd) {

	int result;

	//debug
	//std::cout << "Sending File Not Found (404) response." << std::endl;

	//using sendLine():
	if ((result = sendLine(connFd, "HTTP/1.1 400 Not Found")) != 0) return result; //send properly formmated http response w/ the error code 404
	if ((result = sendLine (connFd, "Content-Type: text/html")) != 0) return result; //send content type message
	if ((result = sendLine (connFd, "")) != 0) return result; //blank line
	if ((result = sendLine (connFd, "<html><body><h1>404 Not Found</h1></body></html>")) != 0) return result; //friendly message
	if ((result = sendLine (connFd, "")) != 0) return result; //black line indicating end of message

	return 0;
}

int send400(int connFd) {
	int result;

	std::cout << "Sending Bad Request (400) response." << std::endl;

	if ((result = sendLine(connFd, "HTTP/1.1 400 Bad Request")) != 0) return result; //send a properly formatted HTTP response with error code 400
	if ((result = sendLine(connFd, "")) != 0) return result; //blank line

	return 0;
}

int send200(int connFd, const std::string& filename) {
	struct stat fileStat; //use stat() function to find size of file
	std::string fullPath = "./" + filename;

	if (stat(fullPath.c_str(), &fileStat) == -1 || S_ISDIR(fileStat.st_mode)) { //check if stat function fails, dont read permission or check if file doesn't exist. send 404 and exit
		send404(connFd);
		return -1;
	}

	//debug
	//std::cout << "Attempting to open file: " << fullPath << std::endl;

	//call open() to open file in binary
	int fileFd = open(fullPath.c_str(), O_RDONLY);

	if (fileFd == -1) {
		std::cout << "Failed to open file: " << strerror(errno) << std::endl;
		send404(connFd);
		return -1;
	}

	//debug
	//std::cout << "Sending file: " << filename << std::endl;

	//use sendLine() to send the header
	std::string contentType;
	if (filename.find(".html") != std::string::npos) {
		contentType = "text/html";
	} else if (filename.find(".jpg") != std::string::npos || filename.find(".jpeg") != std::string::npos) {
		contentType = "image/jpeg";
	} else {
		contentType = "application/octet-stream";
	} //this handles other file types

	//find content length
	off_t contentLength = fileStat.st_size;

	//send a properly formatted HTTP response with the code 200
	std::string response = "HTTP/1.1 200 OK\r\n";
	response += "Content-Type: " + contentType + "\r\n"; //send content type depending on file type
	response += "Content-Length: " + std::to_string(contentLength) + "\r\n"; //send length type

	if (sendLine(connFd, response) != 0) {
		close(fileFd);
		return -2;
	}

	//send file data using read and write
	const int bufferSize = 1024;
	char buffer[bufferSize];
	ssize_t bytesRead;

	while ((bytesRead = read(fileFd, buffer, sizeof(buffer))) > 0) {
		ssize_t bytesWritten = write(connFd, buffer, bytesRead);

		if (bytesWritten == -1) {
			close(fileFd);
			return -3;
		}

	}

	close(fileFd);
	return 0;
}

//The above section of the code for function send200 was based on the assistance received from Chat GPT, a language model by Open AI.
//Reference: https://chat.openai.com/chatgpt


int processConnection(int connFd) {
	std::string filename;
	int returnCode = readRequest(connFd, filename);

	//this checks for the favicon request so it does not freeze up when it is accessing the file
	if (filename == "favicon.ico") {
		sendLine(connFd, "HTTP/1.1 204 No Content");
		close(connFd);
		return 0;
	}

	// this section of the if statement code was based on the assistance I received from Chat GPT, a language model by Open AI.
	// Reference: https://chat.openai.com/chatgpt

	//checks the correct return code
	if (returnCode == 400) {
		//std::cout << "Bad Request (400) received." << std::endl;
		send400(connFd);

	} else if (returnCode == 404) {
		//std::cout << "File Not Found (404) for: " << filename << std::endl;
		send404(connFd);

	} else {
		//std::cout << "Processing successful request for: " << filename << std::endl;
		send200(connFd, filename);
	}

	close(connFd);

	return 0;
}



// **************************************************************************************
// * main()
// * - Sets up the sockets and accepts new connection until processConnection() returns 1
// **************************************************************************************

int main (int argc, char *argv[]) {

  // ********************************************************************
  // * Process the command line arguments
  // ********************************************************************
  int opt = 0;
  while ((opt = getopt(argc,argv,"v")) != -1) {

    switch (opt) {
    case 'v':
      VERBOSE = true;
      break;
    case ':':
    case '?':
    default:
      std::cout << "useage: " << argv[0] << " -v" << std::endl;
      exit(-1);
    }
  }

  // *******************************************************************
  // * Creating the inital socket is the same as in a client.
  // ********************************************************************
  int listenFd = socket(AF_INET, SOCK_STREAM, 0); // Call socket() to create the socket you will use for lisening.

  //check if the socket is made correctly
  if (listenFd == -1) {
	  std::cout << "Failed to create listening socket " << strerror(errno) << std::endl;
	  exit(-1); // if socket() failed, abort program (can't recover). 
  }


  //DEBUG << "Calling Socket() assigned file descriptor " << listenFd << ENDL;


  // ********************************************************************
  // * The bind() and calls take a structure that specifies the
  // * address to be used for the connection. On the cient it contains
  // * the address of the server to connect to. On the server it specifies
  // * which IP address and port to lisen for connections.
  // ********************************************************************
  struct sockaddr_in servaddr; //define the structure
  srand(time(NULL));
  u_int16_t port = (rand() % 10000) + 1024; //port number
  bzero(&servaddr, sizeof(servaddr)); //zero the whole thing
  servaddr.sin_family = AF_INET; //IPv4 protocal family
  servaddr.sin_addr.s_addr = htonl(INADDR_ANY); //let the system pick the IP address
  servaddr.sin_port = htons(port); //pick random high-number port

  // ********************************************************************
  // * Binding configures the socket with the parameters we have
  // * specified in the servaddr structure.  This step is implicit in
  // * the connect() call, but must be explicitly listed for servers.
  // ********************************************************************
  //
  // Call bind() multiple times if another person is using the port already

  //DEBUG << "Calling bind(" << listenFd << "," << &servaddr << "," << sizeof(servaddr) << ")" << ENDL;

  bool bindSuccessful = false;
  while (!bindSuccessful && port >= 1024) {
	if (bind(listenFd, (struct sockaddr *) &servaddr, sizeof(servaddr)) <0) {
		std::cout << "bind() failed: " << strerror(errno) << std::endl;
		port--; //Try another port
		servaddr.sin_port = htons(port); //Update port in servaddr struct

	//This part of the code is based on assistance Adapted from standard coding samples, a language model by OpenAI
	//Reference: https://openai.com/chatgpt

  } else {
	  bindSuccessful = true; //Bind works
	  std::cout << "Using port: " << port << std::endl;
  	}
  } 

  if (!bindSuccessful) {
	  std::cout << "bind() failed in all ports." << std::endl;
	  exit(-1);
  } 


  // ********************************************************************
  // * Setting the socket to the listening state is the second step
  // * needed to being accepting connections.  This creates a queue for
  // * connections and starts the kernel listening for connections.
  // ********************************************************************
  int listenQueueLength = 1;
  if( listen(listenFd, listenQueueLength) <0) {
	  std::cout << "listen() failed: " << strerror(errno) << std::endl;
	  exit(-1);
  }
  //DEBUG << "Calling listen(" << listenFd << "," << listenQueueLength << ")" << ENDL;

  // ********************************************************************
  // * The accept call will sleep, waiting for a connection.  When 
  // * a connection request comes in the accept() call creates a NEW
  // * socket with a new fd that will be used for the communication.
  // ********************************************************************

  bool quitProgram = false;
  while (!quitProgram) {
    int connFd = accept(listenFd, (struct sockaddr *) NULL, NULL);
    if (connFd < 0) {
	    std::cout << "accept() failed: " << strerror(errno) << std::endl;
	    exit(-1);
    }

    //DEBUG << "Calling accept(" << listenFd << "NULL,NULL)." << ENDL;

    // The accept() call checks the listening queue for connection requests.
    // If a client has already tried to connect accept() will complete the
    // connection and return a file descriptor that you can read from and
    // write to. If there is no connection waiting accept() will block and
    // not return until there is a connection.

    //DEBUG << "We have recieved a connection on " << connFd << ENDL;


    quitProgram = processConnection(connFd);

    close(connFd);
  }

  close(listenFd);

}

#include <bits/stdc++.h>

using namespace std;


typedef long long ll;
typedef vector<ll> vi;
typedef pair<ll, ll> ii;
typedef vector<ii> vii;

// ref: https://stackoverflow.com/questions/23556249/continued-fractions
ii contToFrac(vi a, int size) {
    ll n = 1;
    ll d = a[size - 1];
    for (int i = size - 2; i >= 0; i--) {
        int nextd = d * a[i] + n;
        n = d;
        d = nextd;
    }
    return ii(d, n);
}

vi fracToCont(ii frac) {
    vi a;
    ll n = frac.first;
    ll d = frac.second;
    while (d != 0) { // d = 0 means n is divisible by d
        a.push_back(n / d);
        n = n % d;
        swap(n, d);
    }
    return a;
}

ii fracAdd(ii a, ii b) {
    return ii(a.first * b.second + a.second * b.first, a.second * b.second);
}

ii fracSubtract(ii a, ii b) {
    return ii(a.first * b.second - a.second * b.first, a.second * b.second);
}

ii fracMultiply(ii a, ii b) {
    return ii(a.first * b.first, a.second * b.second);
}

ii fracDivide(ii a, ii b) {
    return ii(a.first * b.second, a.second * b.first);
}

void changeFracToContAndPrint(ii frac) {
    vi a = fracToCont(frac);
    while (a.size() > 1 && a.back() == 0) a.pop_back();
    for (int i = 0; i < a.size(); i++) {
        if (i < a.size() - 1) cout << a[i] << " ";
        else cout << a[i] << '\n';
    }
}

// NOTE ABOVE typedef i lazily replaced int into long long...

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    //freopen("error.txt", "w", stderr);

    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n1, n2;
    cin >> n1 >> n2;
    vi a(n1), b(n2);
    for (int i = 0; i < n1; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n2; i++) {
        cin >> b[i];
    }
    ii frac1 = contToFrac(a, n1);
    ii frac2 = contToFrac(b, n2);
    // add
    ii frac = fracAdd(frac1, frac2);
    changeFracToContAndPrint(frac);
    // subtract
    frac = fracSubtract(frac1, frac2);
    changeFracToContAndPrint(frac);
    // multiply
    frac = fracMultiply(frac1, frac2);
    changeFracToContAndPrint(frac);
    // divide
    frac = fracDivide(frac1, frac2);
    changeFracToContAndPrint(frac);

    cerr << "time taken : " << (float) clock() / CLOCKS_PER_SEC << " secs" << '\n';
    return 0;
}


