#ifndef BUFFER_POOL_MANAGER_CPP
#define BUFFER_POOL_MANAGER_CPP

#include "buffer/buffer_pool_manager.h"
#include "buffer/lru_replacer.h"
#include "common/logger.h"
#include "recovery/log_manager.h"
#include "storage/page/page_header.h"

namespace TinyDB {

BufferPoolManager::BufferPoolManager(size_t pool_size, DiskManager *disk_manager, LogManager *log_manager)
    : pool_size_(pool_size), disk_manager_(disk_manager), log_manager_(log_manager) {
    // allocate the in-memory page array
    pages_ = new Page[pool_size_];
    // pool size has no meaning for lru replacer, because we(buffer pool manager)
    // are controlling the page num
    replacer_ = new LRUReplacer(pool_size_);

    // initially, every page is in the free list
    for (size_t i = 0; i < pool_size_; i++) {
        free_list_.emplace_back(static_cast<frame_id_t>(i));
    }
}

BufferPoolManager::~BufferPoolManager() {
    delete[] pages_;
    delete replacer_;
}

Page *BufferPoolManager::FetchPage(page_id_t page_id, bool outbound_is_error) {
    std::lock_guard<std::mutex> guard(latch_);

    // if the page is cached
    auto it = page_table_.find(page_id);
    if (it != page_table_.end()) {
        auto page = &pages_[it->second];
        // pin this frame
        replacer_->Pin(it->second);
        // increment the pin count
        page->pin_count_ += 1;
        return page;
    }

    // allocate a new slot
    frame_id_t frame_id = -1;
    if (!free_list_.empty()) {
        // we will use free slot first
        frame_id = free_list_.back();
        free_list_.pop_back();
    } else {
        // otherwise, let's evict a page and reuse it's slot
        if (!replacer_->Evict(&frame_id)) {
            // maybe we should throw runtime error?
            // because this means there is no more slot.
            // or sleep on conditional variable waiting for a slot
            return NULL;
        }

        auto page = &pages_[frame_id];
        if (page->is_dirty_) {
            FlushPageHelper(frame_id);
        }
        // evict this page
        page_table_.erase(page->GetPageId());
    }

    page_table_[page_id] = frame_id;

    auto page = &pages_[frame_id];
    // initialize the in-memory page representation
    page->page_id_ = page_id;
    page->is_dirty_ = false;
    page->pin_count_ = 1;
    disk_manager_->ReadPage(page_id, page->data_, outbound_is_error);

    return page;
}

bool BufferPoolManager::UnpinPage(page_id_t page_id, bool is_dirty) {
    std::lock_guard<std::mutex> guard(latch_);
    // failed to find this page
    auto it = page_table_.find(page_id);
    if (it == page_table_.end()) {
        return false;
    }
    frame_id_t frame_id = it->second;

    // update is_dirty flag
    pages_[frame_id].is_dirty_ = pages_[frame_id].is_dirty_ || is_dirty;

    // failed to unpin this page
    if (pages_[frame_id].pin_count_ == 0) {
        return false;
    }

    pages_[frame_id].pin_count_ -= 1;
    if (pages_[frame_id].pin_count_ == 0) {
        // put it into replacer
        replacer_->Unpin(frame_id);
    }

    return true;
}

bool BufferPoolManager::FlushPage(page_id_t page_id) {
    std::lock_guard<std::mutex> guard(latch_);
    // this page is not cached
    auto it = page_table_.find(page_id);
    if (it == page_table_.end()) {
        return false;
    }

    // flush to disk
    frame_id_t frame_id = it->second;
    FlushPageHelper(frame_id);

    return true;
}

void BufferPoolManager::FlushPageHelper(frame_id_t frame_id) {
    // write ahead log protocol: 
    // before writting a page into disk, all related logs has to be flush into disk first.
    auto page = &pages_[frame_id];
    if (log_manager_ != NULL) {
        // get lsn of current page
        auto header = reinterpret_cast<PageHeader *>(page->GetData());
        auto lsn = header->GetLSN();
        // flush the log and record the time
        auto t1 = std::chrono::steady_clock::now();
        // force the log
        log_manager_->Flush(lsn, true);
        auto t2 = std::chrono::steady_clock::now();
        flush_wait_time_ += std::chrono::duration_cast<std::chrono::milliseconds>(t2 - t1);
    }
    disk_manager_->WritePage(page->GetPageId(), page->GetData());
    page->is_dirty_ = false;
}

Page *BufferPoolManager::NewPage(page_id_t *page_id) {
    std::lock_guard<std::mutex> guard(latch_);

    // no more space
    if (free_list_.empty() && replacer_->Size() == 0) {
        return NULL;
    }

    // allocate new page from disk
    *page_id = disk_manager_->AllocatePage();

    frame_id_t frame_id = -1;
    if (!free_list_.empty()) {
        frame_id = free_list_.back();
        free_list_.pop_back();
    } else {
        if (!replacer_->Evict(&frame_id)) {
            return NULL;
        }

        auto page = &pages_[frame_id];
        if (page->is_dirty_) {
            FlushPageHelper(frame_id);
        }

        page_table_.erase(page->GetPageId());
    }
    page_table_[*page_id] = frame_id;

    auto page = &pages_[frame_id];
    // initialize the in-memory page representation
    page->page_id_ = *page_id;
    page->is_dirty_ = false;
    page->pin_count_ = 1;
    page->ZeroData();

    return page;
}

bool BufferPoolManager::DeletePage(page_id_t page_id) {
    std::lock_guard<std::mutex> guard(latch_);
    // deallocate this page, return it to disk manager
    disk_manager_->DeallocatePage(page_id);
    auto it = page_table_.find(page_id);
    if (it == page_table_.end()) {
        // already removed
        return true;
    }

    frame_id_t frame_id = page_table_[page_id];
    // check whether other one is still using
    if (pages_[frame_id].pin_count_ > 0) {
        return false;
    }
    // reset page id, because this might interfere "FlushAllPages"
    pages_[frame_id].page_id_ = -1;

    page_table_.erase(page_id);
    // put this slot to free list
    free_list_.push_front(frame_id);
    // remove it from replacer
    replacer_->Pin(frame_id);
    return true;
}

void BufferPoolManager::FlushAllPages() {
    std::lock_guard<std::mutex> guard(latch_);

    // maybe we should iterate hash table?
    for (size_t i = 0; i < pool_size_; i++) {
        if (page_table_.count(pages_[i].GetPageId()) == 0) {
            continue;
        }
        FlushPageHelper(i);
    }
}

bool BufferPoolManager::CheckPinCount() {
    std::lock_guard<std::mutex> guard(latch_);
    bool flag = true;
    for (size_t i = 0; i < pool_size_; i++) {
        if (page_table_.count(pages_[i].GetPageId()) == 0) {
            continue;
        }
        if (pages_[i].GetPinCount() != 0) {
            LOG_ERROR("page %d has pin count %d", pages_[i].GetPageId(), pages_[i].GetPinCount());
            flag = false;
        }
    }
    return flag;
}

}

#endif

#include "il2cpp.hpp"

#include <TlHelp32.h>
#include <ranges>

std::uintptr_t il2cpp::types::il2cpp_t::get_module(const char* const module_name) const
{
    if (const auto process_snapshot = managed_t<HANDLE, CloseHandle>{ CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, process_id) }; process_snapshot.get() != INVALID_HANDLE_VALUE)
    {
        auto module_entry = MODULEENTRY32{ sizeof(MODULEENTRY32) };

        do
        {
            if (!std::strcmp(module_entry.szModule, module_name))
                return reinterpret_cast<std::uintptr_t>(module_entry.modBaseAddr);
        } while (Module32Next(process_snapshot.get(), &module_entry));
    }

    return 0;
}

std::string il2cpp::types::il2cpp_t::read_string(std::uintptr_t address) const
{
    std::string buffer;

    do
        buffer.push_back(read<char>(address++));
    while (read<char>(address) != '\0');

    return buffer;
}

const il2cpp::types::il2cpp_t::images_t& il2cpp::types::il2cpp_t::get_images() const
{
    return images;
}

std::optional<std::reference_wrapper<const il2cpp::types::il2cpp_image_t>> il2cpp::types::il2cpp_t::get_image(const std::string& image_name) const
{
    const auto images_iterator = std::ranges::find(images, image_name, &std::pair<std::string, il2cpp_image_t>::first);

    return images_iterator == images.cend() ? std::nullopt : std::make_optional(std::ref(images_iterator->second));
}

il2cpp::types::il2cpp_t::il2cpp_t(const char* const window_name)
{
    const auto process_window = FindWindowA(nullptr, window_name);

    GetWindowThreadProcessId(process_window, &process_id);

    process_handle = managed_t<HANDLE, CloseHandle>{ OpenProcess(PROCESS_ALL_ACCESS, false, process_id) };

    game_assembly = get_module("GameAssembly.dll");

    const auto assemblies_end = read<std::uintptr_t>(game_assembly + offsets::assembly::assemblies_end);

    for (auto current_assembly = read<std::uintptr_t>(game_assembly + offsets::assembly::assemblies_begin); current_assembly < assemblies_end; current_assembly += sizeof(std::uintptr_t))
        images.emplace_back(read_string(read<std::uintptr_t>(read<std::uintptr_t>(current_assembly) + 0x18)), il2cpp_image_t{ read<std::uintptr_t>(read<std::uintptr_t>(current_assembly)), *this });
}

// Template, 2024 IGAD Edition
// Get the latest version from: https://github.com/jbikker/tmpl8
// IGAD/NHTV/BUAS/UU - Jacco Bikker - 2006-2024

#include "precomp.h"

#define STB_IMAGE_IMPLEMENTATION
#define STBI_NO_PSD
#define STBI_NO_PIC
#define STBI_NO_PNM
#include "lib/stb_image.h"

using namespace Tmpl8;

// Surface class implementation

Surface::Surface( int w, int h, uint* b ) : pixels( b ), width( w ), height( h ) {}

Surface::Surface( int w, int h ) : width( w ), height( h )
{
	pixels = (uint*)MALLOC64( w * h * sizeof( uint ) );
	ownBuffer = true; // needs to be deleted in destructor
}
Surface::Surface( const char* file ) : pixels( 0 ), width( 0 ), height( 0 )
{
	// check if file exists; show an error if there is a problem
	FILE* f = fopen( file, "rb" );
	if (!f) FatalError( "File not found: %s", file );
	fclose( f );
	// load the file
	Surface::LoadFromFile( file );
}

void Surface::LoadFromFile( const char* file )
{
	// use stb_image to load the image file
	int n;
	unsigned char* data = stbi_load( file, &width, &height, &n, 0 );
	if (!data) return; // load failed
	pixels = (uint*)MALLOC64( width * height * sizeof( uint ) );
	ownBuffer = true; // needs to be deleted in destructor
	const int s = width * height;
	if (n == 1) /* greyscale */ for (int i = 0; i < s; i++)
	{
		const unsigned char p = data[i];
		pixels[i] = p + (p << 8) + (p << 16);
	}
	else
	{
		for (int i = 0; i < s; i++) pixels[i] = (data[i * n + 0] << 16) + (data[i * n + 1] << 8) + data[i * n + 2];
	}
	// free stb_image data
	stbi_image_free( data );
}

Surface::~Surface()
{
	if (ownBuffer) FREE64( pixels ); // free only if we allocated the buffer ourselves
}

void Surface::Clear( uint c )
{
	// WARNING: not the fastest way to do this.
	const int s = width * height;
	for (int i = 0; i < s; i++) pixels[i] = c;
}

void Surface::Plot( int x, int y, uint c )
{
	if (x < 0 || y < 0 || x >= width || y >= height) return;
	pixels[x + y * width] = c;
}

void Surface::Box( int x1, int y1, int x2, int y2, uint c )
{
	Line( (float)x1, (float)y1, (float)x2, (float)y1, c );
	Line( (float)x2, (float)y1, (float)x2, (float)y2, c );
	Line( (float)x1, (float)y2, (float)x2, (float)y2, c );
	Line( (float)x1, (float)y1, (float)x1, (float)y2, c );
}

void Surface::Bar( int x1, int y1, int x2, int y2, uint c )
{
	// clipping
	if (x1 < 0) x1 = 0;
	if (x2 >= width) x2 = width - 1;
	if (y1 < 0) y1 = 0;
	if (y2 >= height) y2 = height - 1;
	// draw clipped bar
	uint* a = x1 + y1 * width + pixels;
	for (int y = y1; y <= y2; y++)
	{
		for (int x = 0; x <= (x2 - x1); x++) a[x] = c;
		a += width;
	}
}

// draw a circle using midpoint circle algorithm
// this code is Supported via standard programming aids but after getting the code and making sure that it works,
// I researched for midpoint algorithm and read about it from these sources:
// https://www.gatevidyalay.com/mid-point-circle-drawing-algorithm/
// https://www.geeksforgeeks.org/mid-point-circle-drawing-algorithm/
void Surface::Circle(int x0, int y0, int radius, uint c)
{
	int x = radius;
	int y = 0;
	int xChange = 1 - (radius << 1); // Initial xChange
	int yChange = 0;
	int radiusError = 0;

	while(x >= y)
	{
		// Plot points in all eight octants
		Plot(x0 + x, y0 + y, c);
		Plot(x0 - x, y0 + y, c);
		Plot(x0 + x, y0 - y, c);
		Plot(x0 - x, y0 - y, c);
		Plot(x0 + y, y0 + x, c);
		Plot(x0 - y, y0 + x, c);
		Plot(x0 + y, y0 - x, c);
		Plot(x0 - y, y0 - x, c);

		y++; // Move to the next row
		radiusError += yChange; // Update the error term
		yChange += 2; // Adjust yChange for the next row

		// Check if we need to move x inward
		if((radiusError << 1) + xChange > 0)
		{
			x--; // Move x inward
			radiusError += xChange; // Update the error term
			xChange += 2; // Adjust xChange for the next column
		}
	}
}

void Surface::PrintAsText()
{
	for(int i = 0; i < height; ++i)
	{
		for(int j = 0; j < width; ++j)
		{
			char toPrint =  pixels[j + i * width] != 0 ? '#' : '.';
			printf("%c ",toPrint);
		}
		printf("\n");
	}
}

// Surface::Print: Print some text with the hard-coded mini-font.
void Surface::Print( const char* s, int x1, int y1, uint c )
{
	if (!fontInitialized)
	{
		// we will initialize the font on first use
		InitCharset();
		fontInitialized = true;
	}
	uint* t = pixels + x1 + y1 * width;
	for (int i = 0; i < (int)(strlen( s )); i++, t += 6)
	{
		int pos = 0;
		if ((s[i] >= 'A') && (s[i] <= 'Z')) pos = transl[(unsigned short)(s[i] - ('A' - 'a'))];
		else pos = transl[(unsigned short)s[i]];
		uint* a = t;
		const char* u = (const char*)font[pos];
		for (int v = 0; v < 5; v++, u++, a += width)
			for (int h = 0; h < 5; h++) if (*u++ == 'o') *(a + h) = c, * (a + h + width) = 0;
	}
}

// Surface::Line: Draw a line between the specified screen coordinates.
// Uses clipping for lines that are partially off-screen. Not efficient.
void Surface::Line( float x1, float y1, float x2, float y2, uint c )
{
	// clip (Cohen-Sutherland, https://en.wikipedia.org/wiki/Cohen%E2%80%93Sutherland_algorithm)
	const float xmin = 0, ymin = 0, xmax = (float)width - 1, ymax = (float)height - 1;
	int c0 = OUTCODE( x1, y1 ), c1 = OUTCODE( x2, y2 );
	bool accept = false;
	while (1)
	{
		if (!(c0 | c1)) { accept = true; break; }
		else if (c0 & c1) break; else
		{
			float x = 0, y = 0;
			const int co = c0 ? c0 : c1;
			if (co & 8) x = x1 + (x2 - x1) * (ymax - y1) / (y2 - y1), y = ymax;
			else if (co & 4) x = x1 + (x2 - x1) * (ymin - y1) / (y2 - y1), y = ymin;
			else if (co & 2) y = y1 + (y2 - y1) * (xmax - x1) / (x2 - x1), x = xmax;
			else if (co & 1) y = y1 + (y2 - y1) * (xmin - x1) / (x2 - x1), x = xmin;
			if (co == c0) x1 = x, y1 = y, c0 = OUTCODE( x1, y1 );
			else x2 = x, y2 = y, c1 = OUTCODE( x2, y2 );
		}
	}
	if (!accept) return;
	float b = x2 - x1, h = y2 - y1, l = fabsf( b );
	if (fabsf( h ) > l) l = fabsf( h );
	int il = (int)l;
	float dx = b / (float)l, dy = h / (float)l;
	for (int i = 0; i <= il; i++, x1 += dx, y1 += dy)
		*(pixels + (int)x1 + (int)y1 * width) = c;
}

// Surface::CopyTo: Copy the contents of one Surface to another, at the specified
// location. With clipping.
void Surface::CopyTo( Surface* d, int x, int y )
{
	uint* dst = d->pixels;
	uint* src = pixels;
	if ((src) && (dst))
	{
		int srcwidth = width;
		int srcheight = height;
		int dstwidth = d->width;
		int dstheight = d->height;
		if ((srcwidth + x) > dstwidth) srcwidth = dstwidth - x;
		if ((srcheight + y) > dstheight) srcheight = dstheight - y;
		if (x < 0) src -= x, srcwidth += x, x = 0;
		if (y < 0) src -= y * srcwidth, srcheight += y, y = 0;
		if ((srcwidth > 0) && (srcheight > 0))
		{
			dst += x + dstwidth * y;
			for (int i = 0; i < srcheight; i++)
			{
				memcpy( dst, src, srcwidth * 4 );
				dst += dstwidth, src += width;
			}
		}
	}
}

void Surface::SetChar( int c, const char* c1, const char* c2, const char* c3, const char* c4, const char* c5 )
{
	strcpy( font[c][0], c1 );
	strcpy( font[c][1], c2 );
	strcpy( font[c][2], c3 );
	strcpy( font[c][3], c4 );
	strcpy( font[c][4], c5 );
}

