        return jsonData;
    }

    std::string url(IEX_ENDPOINT);
    url += "/stock/"+symbol+"/time-series";
    IEX::sendGetRequest(jsonData, url);
    assert(jsonData.isArray()); //Crash if not an array
    return jsonData;
}

