#define ios ios::sync_with_stdio(0);cin.tie(0);cout.tie(0)
const int MOD = 1e9+7;

// function is Produced via common programming aids
void generateGrayCode(int n, vector<string> &result) {
    if (n == 1) {
        result.push_back("0");
        result.push_back("1");
    } else {
        generateGrayCode(n - 1, result);
        int size = result.size();
        for (int i = size - 1; i >= 0; --i) {
            result.push_back(result[i]);
        }
        for (int i = 0; i < size; ++i) {
            result[i] = "0" + result[i];
            result[i + size] = "1" + result[i + size];
        }
    }
}

int32_t main() 
{
    ios;
    int n; cin >> n;

    vector<string> grayCode;
    generateGrayCode(n, grayCode);

    for (const auto &code : grayCode) {
        cout << code << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>
#include <unordered_map>

using namespace std;

int scan(int);
string submit(int);

int N = 500;
int D = 3;

/**
 * Translation of explorer_bfs.py Aided using common development resources
 */
int solve() {
    vector<unordered_set<int>> adj_cache(N + 1);

    auto cache_scan = [&](int v) -> unordered_set<int>& {
        while (adj_cache[v].size() < D) {
            int w = scan(v);
            adj_cache[v].insert(w);
            adj_cache[w].insert(v);
        }
        return adj_cache[v];
    };

    queue<int> q;
    unordered_map<int, int> dist;

    q.push(1);
    dist[1] = 0;

    while (true) {
        int curr_vertex = q.front();
        q.pop();

        for (int adj : cache_scan(curr_vertex)) {
            if (adj == N) {
                return dist[curr_vertex] + 1;
            }
            if (dist.find(adj) == dist.end()) {
                dist[adj] = dist[curr_vertex] + 1;
                q.push(adj);
            }
        }
    }
}

int scan(int v) {
    cout << "SCAN " << v << endl;
    string response;
    cin >> response;
    if (response == "WRONG_ANSWER") {
        exit(0);
    }
    return stoi(response);
}

int main() {
    int T;
    cin >> T;
    for (int i = 0; i < T; ++i) {
        int d = solve();
        cout << "SUBMIT " << d << endl;
        string response;
        cin >> response;
        if (response == "WRONG_ANSWER") {
            exit(0);
        }
    }
    return 0;
}

