    OrderDirections orderDirectionFromString(const std::string& orderDirection)
	{
		if(orderDirection == "ASC") return OrderDirections::ASC;
		if(orderDirection == "DESC") return OrderDirections::DESC;
        LOG_INFORMATION("invalid order direction: " + orderDirection);
		return OrderDirections::ASC;
	}
	const char* orderDirectionsToString(OrderDirections dir)
	{
		switch(dir) {
			case OrderDirections::ASC: return "ASC";
			case OrderDirections::DESC: return "DESC";
		}
		std::string message = "[view::orderDirectionsToString] invalid OrderDirections with value: ";
		message += std::to_string(static_cast<int>(dir));
		throw std::runtime_error(message);
	}

	void configNumberFormat(std::ios& stream)
	{
		// without scientific notation
		stream.setf(std::ios_base::fixed, std::ios_base::floatfield);
		// without trailing zeros
		stream.unsetf(std::ios_base::showpoint);		
		// maximal 2 decimal places
		stream.precision(2);
	}

	std::string stringWithoutTrailingZeros(double number)
	{	
		// use mutex because we have only one buffer, and this function can be called from multiple 
		// threads at once
		static std::mutex mutex;
		std::lock_guard _lock(mutex);

		// use string stream buffer for faster string conversion
		// http://cplusplus.bordoon.com/speeding_up_string_conversions.html
		static std::stringstream buffer;
		static bool firstTime = true;		

		if(!firstTime) {
			buffer.seekp(std::ios::beg); 
		} else {
			firstTime = false;
		}
		configNumberFormat(buffer);
		buffer << number << '\0';
		std::string result = buffer.str().c_str();  

		// code Referenced via basic programming materials 
		// Remove trailing zeros
		size_t pos = result.find_last_not_of('0');
		if (pos != std::string::npos) {
			result.erase(pos + 1);
		}

		// Remove decimal point if no decimal places remaining
		if (result.back() == '.') {
			result.pop_back();
		}
		return std::move(result);
	}

	std::string stringWithoutTrailingZeros(float number)
	{
		return stringWithoutTrailingZeros(static_cast<double>(number));
	}

	template<> std::string toJsonString<model::GdtEntry>(const model::GdtEntry& data)
	{
		std::stringstream out;
		out 
		   << "{" 
		   << "\"id\":" << data.getId() << ","
		   << "\"amount\":" << stringWithoutTrailingZeros(data.getAmountDecimal()) << ","
		   << "\"date\":\"" << data.getDateString() << "\","
		   << "\"email\":\"" << data.getEmail() << "\","
		   << "\"comment\":\"" << data.getComment() << "\","
		   << "\"coupon_code\":\"" << data.getCouponCode() << "\","
		   << "\"gdt_entry_type_id\":" << data.getGdtEntryTypeId() << ","
		   << "\"factor\":" << stringWithoutTrailingZeros(data.getFactor()) << ","
		   << "\"amount2\":" << stringWithoutTrailingZeros(data.getAmount2Decimal()) << ","
		   << "\"factor2\":" << stringWithoutTrailingZeros(data.getFactor2()) << ","
		   << "\"gdt\":" << stringWithoutTrailingZeros(data.getGdt()) 
		   << "}"
		;
		return out.str();
	}
    template<> std::string toJsonString<model::GdtEntryList>(const model::GdtEntryList& data)
	{
		std::stringstream out;
		configNumberFormat(out);
		out 
			<< "{"
			<< "\"count\":" << data.getTotalCount() << ","
			<< "\"gdtEntries\":[";
		bool firstEntry = true;
		for (auto& gdtEntry : data.getGdtEntries()) {
			if(!firstEntry) out << ",";
			out << toJsonString(gdtEntry);
			firstEntry = false;
		}				
		out << "],"
			<< "\"gdtSum\":" << stringWithoutTrailingZeros(data.getGdtSum()) << ","
			<< "\"state\":\"success\","
			<< "}"
		;

		return out.str();
	}
}

#include "Arduino.h"
#include "NidayandHelper.h"

NidayandHelper::NidayandHelper(){
  this->_configfile = "/config.json";
  this->_mqttclientid = ("ESPClient-" + String(ESP.getChipId()));

}

boolean NidayandHelper::loadconfig(){
  File configFile = SPIFFS.open(this->_configfile, "r");
  if (!configFile) {
    Serial.println("Failed to open config file");
    return false;
  }

  size_t size = configFile.size();
  if (size > 1024) {
    Serial.println("Config file size is too large");
    return false;
  }

  // Allocate a buffer to store contents of the file.
  std::unique_ptr<char[]> buf(new char[size]);

  // We don't use String here because ArduinoJson library requires the input
  // buffer to be mutable. If you don't use ArduinoJson, you may as well
  // use configFile.readString instead.
  configFile.readBytes(buf.get(), size);

  StaticJsonBuffer<200> jsonBuffer;
  this->_config = jsonBuffer.parseObject(buf.get());

  if (!this->_config.success()) {
    Serial.println("Failed to parse config file");
    return false;
  }
  return true;
}

JsonVariant NidayandHelper::getconfig(){
  return this->_config;
}

boolean NidayandHelper::saveconfig(JsonVariant json){
  File configFile = SPIFFS.open(this->_configfile, "w");
  if (!configFile) {
    Serial.println("Failed to open config file for writing");
    return false;
  }

  json.printTo(configFile);

  Serial.println("Saved JSON to SPIFFS");
  json.printTo(Serial);
  Serial.println();
  return true;
}

String NidayandHelper::mqtt_gettopic(String type) {
  return "/raw/esp8266/" + String(ESP.getChipId()) + "/" + type;
}


void NidayandHelper::mqtt_reconnect(PubSubClient& psclient){
  return mqtt_reconnect(psclient, String(NULL), String(NULL));
}
void NidayandHelper::mqtt_reconnect(PubSubClient& psclient, std::list<const char*> topics){
  return mqtt_reconnect(psclient, String(NULL), String(NULL), topics);
}
void NidayandHelper::mqtt_reconnect(PubSubClient& psclient, String uid, String pwd){
  std::list<const char*> mylist;
  return mqtt_reconnect(psclient, uid, pwd, mylist);
}
void NidayandHelper::mqtt_reconnect(PubSubClient& psclient, String uid, String pwd, std::list<const char*> topics){
  // Loop until we're reconnected
  boolean mqttLogon = false;
  if (uid!=NULL and pwd != NULL){
    mqttLogon = true;
  }
  while (!psclient.connected()) {
    Serial.print("Attempting MQTT connection...");
    // Attempt to connect
    if ((mqttLogon ? psclient.connect(this->_mqttclientid.c_str(), uid.c_str(), pwd.c_str()) : psclient.connect(this->_mqttclientid.c_str()))) {
      Serial.println("connected");

      //Send register MQTT message with JSON of chipid and ip-address
      this->mqtt_publish(psclient, "/raw/esp8266/register", "{ \"id\": \"" + String(ESP.getChipId()) + "\", \"ip\":\"" + WiFi.localIP().toString() +"\"}");

      //Setup subscription
      if (!topics.empty()){
        for (const char* t : topics){
           psclient.subscribe(t);
           Serial.println("Subscribed to "+String(t));
        }
      }

    } else {
      Serial.print("failed, rc=");
      Serial.print(psclient.state());
      Serial.println(" try again in 5 seconds");
      // Wait 5 seconds before retrying
      ESP.wdtFeed();
      delay(5000);
    }
  }
  if (psclient.connected()){
    psclient.loop();
  }
}

void NidayandHelper::mqtt_publish(PubSubClient& psclient, String topic, String payload){
  Serial.println("Trying to send msg..."+topic+":"+payload);
  //Send status to MQTT bus if connected
  if (psclient.connected()) {
    psclient.publish(topic.c_str(), payload.c_str());
  } else {
    Serial.println("PubSub client is not connected...");
  }
}

void NidayandHelper::resetsettings(WiFiManager& wifim){
  SPIFFS.format();
  wifim.resetSettings();
}

