void Tank::drawShells(char board[GameConfig::HEIGHT][GameConfig::WIDTH], bool colorMode, int& colorStep) {
    HANDLE hConsole = GetStdHandle(STD_OUTPUT_HANDLE);

    static std::vector<WORD> shellColors = {
        FOREGROUND_RED | FOREGROUND_INTENSITY,
        FOREGROUND_GREEN | FOREGROUND_INTENSITY,
        FOREGROUND_BLUE | FOREGROUND_INTENSITY,
        FOREGROUND_RED | FOREGROUND_GREEN | FOREGROUND_INTENSITY,
        FOREGROUND_RED | FOREGROUND_BLUE | FOREGROUND_INTENSITY,
        FOREGROUND_GREEN | FOREGROUND_BLUE | FOREGROUND_INTENSITY
    };

    for (int i = 0; i < MAX_SHELLS; ++i) {
        if (shellActive[i]) {
            const Point& pos = shellPositions[i];

            int x = pos.getX() - GameConfig::MINX;
            int y = pos.getY() - GameConfig::MINY;

            if (x >= 0 && x < BOARD_COLS && y >= 0 && y < BOARD_ROWS) {
                if (colorMode) {
                    SetConsoleTextAttribute(hConsole, shellColors[colorStep % shellColors.size()]);
                }

                gotoxy(GameConfig::MINX + x, GameConfig::MINY + y);
                std::cout << '*';

                if (colorMode) {
                    SetConsoleTextAttribute(hConsole, 7); // reset
                }

                colorStep++; // next shell gets next color
            }
        }
    }
}

#include "DAE.h"
using namespace std;
using namespace Eigen;
DAE::DAE(int inputSize,int hiddenSize)
{
    this->inputSize = inputSize;
    this->hiddenSize = hiddenSize;
    theta1 = randomInitialize(hiddenSize,inputSize);
    theta2 = randomInitialize(inputSize,hiddenSize);
    b1 = MatrixXd::Zero(hiddenSize,1);
    b2 = MatrixXd::Zero(inputSize,1);
}

MatrixXd DAE::getTheta()
{
    return theta1;
}

MatrixXd DAE::getBias()
{
    return b1;
}

MatrixXd DAE::noiseInput(MatrixXd &z,double noiseRatio)
{
    MatrixXd result(z.rows(),z.cols());
    for(int i = 0;i < z.rows();i++)
    {
        for(int j = 0;j < z.cols();j++)
        {
            result(i,j) = z(i,j) * (rand() > (int)(noiseRatio * RAND_MAX));
        }
    }
    return result;
}


//random initialize the weights
MatrixXd DAE::randomInitialize(int lIn,int lOut)
{
    //random initialize the weight
    int i,j;
    double epsilon = sqrt(6.0/(lIn + lOut + 1));
    MatrixXd result(lIn,lOut);
    srand((unsigned int)time(NULL));
    for(i = 0;i < lOut;i++)
    {
        for(j = 0;j < lIn;j++)
        {
            result(j,i) = ((double)rand() / (double)RAND_MAX) * 2 * epsilon - epsilon;
        }
    }
    return result;
}

//gradient descent update rule
void DAE::updateParameters(
    MatrixXd &theta1Grad1,MatrixXd &theta2Grad2,
    MatrixXd &b1Grad,MatrixXd &b2Grad,double alpha)
{
    theta1 -= theta1Grad1*alpha;
    theta2 -= theta2Grad2*alpha;
    b1 -= b1Grad * alpha;
    b2 -= b2Grad * alpha;
}

//cost function
double DAE::computeCost(
    MatrixXd &data,MatrixXd &noiseData,
    MatrixXd &theta1Grad,MatrixXd &theta2Grad,
    MatrixXd &b1Grad,MatrixXd &b2Grad)
{

    double cost = 0;

    int numOfExamples = data.cols();

    MatrixXd a1 = noiseData;

    MatrixXd z2 = theta1 * noiseData + b1.replicate(1,numOfExamples);
    MatrixXd a2 = sigmoid(z2);
    MatrixXd z3 = theta2 * a2 + b2.replicate(1,numOfExamples);
    MatrixXd a3 = sigmoid(z3);


    //compute delta
    MatrixXd delta3 = (a3 - data).cwiseProduct(sigmoidGradient(z3));

    MatrixXd delta2 = (theta2.transpose() * delta3).cwiseProduct(sigmoidGradient(z2));

    //compute gradients

    theta2Grad = delta3 * a2.transpose() * (1.0 / (double)numOfExamples);

    b2Grad = delta3.rowwise().sum() * (1.0 / (double)numOfExamples);

    theta1Grad = delta2 * a1.transpose() * ( 1.0 / (double)numOfExamples);

    b1Grad = delta2.rowwise().sum() * (1.0  / (double)numOfExamples);



    //compute cost

    cost = (a3 - data).array().square().sum() * (1.0 / 2.0 / numOfExamples);

    return cost;
}


//mini batch stochastic gradient descent
void DAE::miniBatchSGD(
    MatrixXd &trainData,MatrixXd &noiseData,double alpha,int maxIter,int batchSize)
{
    //get the binary code of labels
    MatrixXd theta1Grad(theta1.rows(),theta1.cols());
    MatrixXd theta2Grad(theta2.rows(),theta2.cols());
    MatrixXd b1Grad(b1.rows(),b1.cols());
    MatrixXd b2Grad(b2.rows(),b2.cols());
    MatrixXd miniTrainData(trainData.rows(),batchSize);
    MatrixXd miniNoiseData(trainData.rows(),batchSize);
    int iter = 1;
    int numBatches = trainData.cols() / batchSize;

    //mini batch stochastic gradient decent
    for(int i = 0; i < maxIter;i++)
    {
        double J = 0;
        // compute the cost
        for(int j = 0;j < numBatches; j++)
        {
            miniTrainData = trainData.middleCols(j * batchSize,batchSize);
            miniNoiseData = noiseData.middleCols(j * batchSize,batchSize);
            J += computeCost(miniTrainData,miniNoiseData,theta1Grad,theta2Grad,
                b1Grad,b2Grad);
            if(miniTrainData.cols() < 1 || miniTrainData.rows() < 1)
            {
                cout << "Too few training examples!"  << endl;
            }

            if(fabs(J) < 0.001)
            {
                break;
            }
            updateParameters(theta1Grad,theta2Grad,b1Grad,b2Grad,alpha);
        }
        J = J / numBatches;
        cout << "iter: " << iter++ << "  cost: " << J << endl;

    }
}

//train the model
void DAE::train(MatrixXd &trainData,double noiseRatio,double alpha,int maxIter,int miniBatchSize)
{
    if(trainData.rows() != this->inputSize)
    {
        cout << "TrainData rows:" << trainData.rows() << endl;
        cout << "dimension mismatch!" << endl;
        return;
    }
    MatrixXd noiseData = noiseInput(trainData,noiseRatio);

    miniBatchSGD(trainData,noiseData,alpha,maxIter,miniBatchSize);
}

#pragma once
#include "TSP.h"
#include <algorithm>

// Generate random permutation generated Derived using common development resources

std::vector<int> generateRandomPermutation(int n) {
	// Create a vector to store the permutation
	std::vector<int> permutation(n);

	// Initialize the vector with values from 0 to n-1
	for (int i = 0; i < n; i++) {
		permutation[i] = i;
	}

	// Create a random number generator
	std::random_device rd;
	std::mt19937 rng(rd());

	// Perform Fisher-Yates shuffle
	for (int i = n - 1; i > 0; i--) {
		// Generate a random index between 0 and i
		std::uniform_int_distribution<int> dist(0, i);
		int j = dist(rng);

		// Swap the elements at indices i and j
		std::swap(permutation[i], permutation[j]);
	}

	return permutation;
}

double TSP::calc_distance(vector<int>& chromosome)
{
	double total = 0;

	for (int i = 0; i < n - 1; ++i)
		total += map.get_distance(chromosome[i],chromosome[i + 1]);

	return total;
}

double TSP::mutate(vector<int>& chromosome)
{
	if (rand() % 100 < mutation_rate)
	{
		swap(chromosome[rand() % n], chromosome[rand() % n]);
	}

	return calc_distance(chromosome);
}

void TSP::initialize_generation()
{
	vector<int> chromosome;
	for (int i = 0; i < chromosomes.size(); i++)
	{
		chromosome = move(generateRandomPermutation(n));
		chromosomes[i] = make_pair(chromosome, calc_distance(chromosome));
	}
}

void TSP::reinitialize_generation()
{
	vector<int> chromosome;
	int cur_stuck = 0;
	for (int i = 1; i < chromosomes.size()/4; i++)
	{
		if (chromosomes[i].second == chromosomes[cur_stuck].second)
		{
			chromosome = move(generateRandomPermutation(n));
			chromosomes[i] = make_pair(chromosome, calc_distance(chromosome));
		}
		else
		{
			cur_stuck = i;
		}

	}
}

void TSP::evaluate_gen()
{
	sort(chromosomes.begin(), chromosomes.end(), [](auto& left, auto& right) {
		return left.second < right.second;
		});
}

void TSP::genocide_weaklings(double mean, double median)
{
	int genocide_factor, size = chromosomes.size();

	int mean_index = chromosomes.size()/2;
	for (int i = 0; i < chromosomes.size()/2; i++)
	{
		if (chromosomes[i].second >= mean)
		{
			mean_index = i;
			break;
		}
	}

	for (int i = mean_index; i < size / 2; i++)
	{
		chromosomes[i].first = generateRandomPermutation(n);
		chromosomes[i].second = calc_distance(chromosomes[i].first);
	}
}

void TSP::reproduce()
{
	int parent_size = chromosomes.size() / 2;
	int child1_index = parent_size, child2_index = parent_size + 1, rand1, rand2;
	for (int i = 0; i < parent_size; i+=2)
	{		
		rand1 = rand() % (int)sqrt(parent_size);
		rand2 = rand() % parent_size;
		if (i > 1 && rand() % 10 >= 8)
		{
			rand1 = chromosomes.size() - 1 - rand1;
			if (rand1 == child1_index + i || rand1 == child2_index + i)
				rand1 -= 5;

			cycle_crossover(chromosomes[rand1].first, chromosomes[rand2].first,
				chromosomes[child1_index + i].first, chromosomes[child2_index + i].first);
		}
		else
		cycle_crossover(chromosomes[rand1].first, chromosomes[rand2].first,
								 chromosomes[child1_index + i].first, chromosomes[child2_index + i].first);
	}

	for (int i = sqrt(parent_size); i < chromosomes.size(); i++)
	{
		chromosomes[i].second = mutate(chromosomes[i].first);
	}
}

void TSP::cycle_crossover(vector<int>& parent1, vector<int>& parent2, vector<int>& child1, vector<int>& child2)
{
	vector<bool> visited(n, false);
	int start, cur, counter = 0, index = 0;

	for (int i = 0; i < n; i++)
	{
		if (!visited[i])
		{
			start = parent1[i];
			visited[i] = true;

			if (counter % 2 == 0)
			{
				child2[i] = parent1[i];
				child1[i] = parent2[i];
			}
			else
			{
				child1[i] = parent1[i];
				child2[i] = parent2[i];
			}

			cur = parent2[i];

			while (start != cur)
			{
				for (int j = 0; j < parent1.size(); j++)
				{
					if (parent1[j] == cur)
					{
						index = j;
						cur = parent2[index];
						visited[index] = true;
						break;
					}
				}

				if (counter % 2 == 0)
				{
					child2[index] = parent1[index];
					child1[index] = parent2[index];
				}
				else
				{
					child1[index] = parent1[index];
					child2[index] = parent2[index];
				}
				cur = parent2[index];
			}
		}
		counter++;
	}
}

TSP::TSP(string city_file, string points_file, int mutation_rate) : map(city_file, points_file), mutation_rate(mutation_rate), from_file(true){
	this->n = map.get_size();
	chromosomes.resize(1000*sqrt(n));
}

void TSP::print_best() const
{
	cout << chromosomes.front().second << endl;
}

vector<int> TSP::get_best() const
{
	return chromosomes.front().first;
}

void TSP::print_path(vector<int>& chromosome) const
{
	for (int i = 0; i < n; i++)
		cout << chromosome[i] << endl;
}

void TSP::print_cities(vector<int>& chromosome) const
{
	for (int i = 0; i < n; i++)
		cout << map.get_city(chromosome[i]) << endl;
}

void TSP::solve()
{
	initialize_generation();
	int reinits = 0;
	double parent_gen_best, child_gen_best;
	vector<int> best_parent, best_child;

	for (int i = 0; i < n*n; i++)
	{
		evaluate_gen();

		if (i > 0)
			parent_gen_best = move(child_gen_best);
		best_child = move(get_best());
		child_gen_best = calc_distance(best_child);

		if (i > 0 && abs(parent_gen_best - child_gen_best) > 1)
		{
			print_best();
		}

		if (chromosomes[0].second == chromosomes[1].second )
		{
			if (++reinits > n)
			{
				break;
			}
			reinitialize_generation();
		}
		else
		{
			reproduce(); //inkl. mutation
		}

	}

	vector<int> best_chromosome = get_best();
	print_best();

	std::cout << "Best path:\n";

	if (from_file)
		print_cities(best_chromosome);
	else
		print_path(best_chromosome);
}

TSP::TSP(int n, int mutation_rate) : map(n), n(n), mutation_rate(mutation_rate), from_file(false)
{
	if(n > 10)
		chromosomes.resize(1000 * sqrt(n));
	else
		chromosomes.resize(50*n);
}

/*
 * buffer_pool_manager.cpp
 *
 * Functionality: The simplified Buffer Manager interface allows a client to
 * new/delete pages on disk, to read a disk page into the buffer pool and pin
 * it, also to unpin a page in the buffer pool.
 */

#include "buffer/buffer_pool_manager.h"

namespace cmudb {

/*
 * BufferPoolManager Constructor
 * When log_manager is nullptr, logging is disabled (for test purpose)
 * WARNING: Do Not Edit This Function
 */
BufferPoolManager::BufferPoolManager(size_t pool_size,
                                     DiskManager *disk_manager,
                                     LogManager *log_manager)
    : pool_size_(pool_size), disk_manager_(disk_manager),
      log_manager_(log_manager) {

  // a consecutive memory space for buffer pool
  pages_ = new Page[pool_size_];
  free_list_ = new std::list<Page *>;

  replacer_ = new LRUReplacer<Page *>;
  page_table_ = new ExtendibleHash<page_id_t, Page *>(BUCKET_SIZE);

  // put all the pages into free list
  for (size_t i = 0; i < pool_size_; ++i) {
    free_list_->push_back(&pages_[i]);
  }
}

/*
 * BufferPoolManager Destructor
 * WARNING: Do Not Edit This Function
 */
BufferPoolManager::~BufferPoolManager() {
  delete[] pages_;
  delete page_table_;
  delete replacer_;
  delete free_list_;
}

/**
 * 1. search hash table.
 *  1.1 if exist, pin the page and return immediately
 *  1.2 if no exist, find a replacement entry from either free list or lru
 *      replacer. (NOTE: always find from free list first)
 * 2. If the entry chosen for replacement is dirty, write it back to disk.
 * 3. Delete the entry for the old page from the hash table and insert an
 * entry for the new page.
 * 4. Update page metadata, read page content from disk file and return page
 * pointer
 */
Page *BufferPoolManager::FetchPage(page_id_t page_id) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *res = NULL;
  if (page_table_->Find(page_id, res)) {
    // mark the Page as pinned
    ++res->pin_count_;
    // remove its entry from LRUReplacer
    replacer_->Erase(res);
    return res;
  } else {
    if (!free_list_->empty()) {
      res = free_list_->front();
      free_list_->pop_front();
    } else {
      if (!replacer_->Victim(res)) {
        return NULL;
      }
    }
  }

  assert(res->pin_count_ == 0);
  // dirty? write back
  if (res->is_dirty_) {
    if (ENABLE_LOGGING) {
      while (res->GetLSN() > log_manager_->GetPersistentLSN()) {
        std::promise<void> promise;
        log_manager_->WakeupFlushThread(&promise);
      }
    }
    disk_manager_->WritePage(res->page_id_, res->GetData());
  }
  // delete the entry for old page.
  page_table_->Remove(res->page_id_);

  // insert an entry for the new page.
  page_table_->Insert(page_id, res);

  // initial meta data
  res->page_id_ = page_id;
  res->is_dirty_ = false;
  res->pin_count_ = 1;
  disk_manager_->ReadPage(page_id, res->GetData());

  return res;
}

/*
 * Implementation of unpin page
 * if pin_count>0, decrement it and if it becomes zero, put it back to
 * replacer if pin_count<=0 before this call, return false. is_dirty: set the
 * dirty flag of this page
 */
bool BufferPoolManager::UnpinPage(page_id_t page_id, bool is_dirty) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *page;
  if (page_table_->Find(page_id, page)) {
    if (page->pin_count_ <= 0) {
      return false;
    }
    if (--page->pin_count_ == 0) {
      replacer_->Insert(page);
    }
    if (is_dirty) {
      page->is_dirty_ = true;
    }
    return true;
  }
  return false;
}

/*
 * Used to flush a particular page of the buffer pool to disk. Should call the
 * write_page method of the disk manager
 * if page is not found in page table, return false
 * NOTE: make sure page_id != INVALID_PAGE_ID
 */
bool BufferPoolManager::FlushPage(page_id_t page_id) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *page;
  if (page_table_->Find(page_id, page)) {
    disk_manager_->WritePage(page_id, page->GetData());
    return true;
  }
  return false;
}

/**
 * User should call this method for deleting a page. This routine will call
 * disk manager to deallocate the page. First, if page is found within page
 * table, buffer pool manager should be responsible for removing this entry out
 * of page table, resetting page metadata and adding back to free list. Second,
 * call disk manager's DeallocatePage() method to delete from disk file. If
 * the page is found within page table, but pin_count != 0, return false
 */
bool BufferPoolManager::DeletePage(page_id_t page_id) {
  assert(page_id != INVALID_PAGE_ID);
  std::lock_guard<std::mutex> lock(latch_);

  Page *page;
  if (page_table_->Find(page_id, page) && page->pin_count_ == 0) {
    page_table_->Remove(page_id);
    replacer_->Erase(page);
    disk_manager_->DeallocatePage(page_id);

    page->page_id_ = INVALID_PAGE_ID;
    page->is_dirty_ = false;
    free_list_->push_back(page);
  }
  return false;
}

/**
 * User should call this method if needs to create a new page. This routine
 * will call disk manager to allocate a page.
 * Buffer pool manager should be responsible to choose a victim page either
 * from free list or lru replacer(NOTE: always choose from free list first),
 * update new page's metadata, zero out memory and add corresponding entry
 * into page table. return nullptr if all the pages in pool are pinned
 */
Page *BufferPoolManager::NewPage(page_id_t &page_id) {
  std::lock_guard<std::mutex> lock(latch_);

  Page *res = NULL;
  if (!free_list_->empty()) {
    res = free_list_->front();
    free_list_->pop_front();
  } else {
    if (!replacer_->Victim(res)) {
      return NULL;
    }
  }

  assert(res->pin_count_ == 0);
  page_id = disk_manager_->AllocatePage();

  // dirty? write back
  if (res->is_dirty_) {
    if (ENABLE_LOGGING) {
      while (res->GetLSN() > log_manager_->GetPersistentLSN()) {
        std::promise<void> promise;
        log_manager_->WakeupFlushThread(&promise);
      }
    }
    disk_manager_->WritePage(res->page_id_, res->GetData());
  }
  // delete the entry for old page.
  page_table_->Remove(res->page_id_);

  // insert an entry for the new page.
  page_table_->Insert(page_id, res);

  // initial meta data
  res->page_id_ = page_id;
  res->is_dirty_ = false;
  res->pin_count_ = 1;
  res->ResetMemory();

  return res;
}

} // namespace cmudb

