            listNode** currentList = currentGraph->getListRepresentation();
            start = clock();
            DijkstraList(currentList, 0, currentGraph->numNodes);
            end = clock();
            timeTable[i][j+2] = ((double) (end - start)) / CLOCKS_PER_SEC * 1000;
        }
